window.KHO_DATA_L3_MITHUAT = [
{"lop":3,"mon":"Mĩ thuật","tuan":1,"tiet":1,"bai":"Chủ đề 1: EM YÊU MĨ THUẬT","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được một số hoạt động thực hành, sáng tạo mĩ thuật trong và ngoài nhà trường.\n- Nhận ra và phân biệt được sản phẩm mĩ thuật 2D và 3D, sản phẩm mĩ thuật tạo hình và ứng dụng.\n- Gọi tên được một số sản phẩm mĩ thuật quen thuộc.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS kể được các hoạt động mĩ thuật khác nhau qua ảnh và clip.","dodung":"- Giáo viên: một số sản phẩm mĩ thuật 2D, 3D, sản phẩm tạo hình và ứng dụng; video, clip giới thiệu hoạt động mĩ thuật (thực hành ngoài trời, tham quan bảo tàng…); thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem video về các hoạt động vẽ tranh, các sản phẩm mĩ thuật đẹp và hỏi: Em có yêu thích mĩ thuật không?\n- GV nhận xét, khen ngợi và giới thiệu chủ đề bài học.","hs":"- HS xem video, trả lời câu hỏi.\n- HS mở bài học, ghi tên bài vào vở."},{"ten":"2. Khám phá","gv":"- GV mời HS nói những hiểu biết về hoạt động đặc thù của môn Mĩ thuật đã tham gia trong và ngoài trường.\n- GV cho HS quan sát một số sản phẩm mĩ thuật 2D, 3D, tạo hình và ứng dụng; phân tích để HS phân biệt từng loại.\n- GV chốt: sản phẩm 2D là hình phẳng (tranh vẽ, xé dán…); sản phẩm 3D là hình khối (nặn, tạo dáng…).","hs":"- HS kể các hoạt động mĩ thuật đã tham gia: vẽ, xé dán, nặn, làm sản phẩm từ vật liệu tái sử dụng, trưng bày sản phẩm…\n- HS quan sát, phân biệt sản phẩm 2D và 3D, tạo hình và ứng dụng."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS viết/vẽ những sản phẩm mĩ thuật muốn thực hiện trong năm học vào Vở bài tập hoặc giấy nháp.\n- GV quan sát, động viên, khen ngợi HS.","hs":"- HS viết/vẽ ý tưởng sản phẩm mĩ thuật mong muốn thực hiện.\n- HS chia sẻ trước lớp."},{"ten":"4. Vận dụng","gv":"- GV yêu cầu HS nêu lại kiến thức bài học và liên hệ mĩ thuật với cuộc sống xung quanh.\n- GV dặn dò chuẩn bị chủ đề Hoa văn trên trang phục.","hs":"- HS nêu lại kiến thức, liên hệ thực tế.\n- HS chuẩn bị đồ dùng cho bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ ảnh và clip ngắn về các hoạt động mĩ thuật trong và ngoài nhà trường: vẽ tranh tường, làm gốm, nặn tò he, trưng bày sản phẩm; HS thấy mĩ thuật không chỉ là vẽ trên giấy.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS xếp các ảnh trên màn hình thành hai nhóm sản phẩm hai chiều và sản phẩm ba chiều, nói rõ mình căn cứ vào đâu để xếp.\n⚠ (Miền 4: An toàn) GV mở tập ảnh đã chuẩn bị sẵn trước giờ học; HS xem màn hình khoảng mười phút thì nghỉ mắt, nhìn ra xa hoặc nhắm mắt vài giây rồi mới xem tiếp.","hs":"- HS kể được các hoạt động mĩ thuật khác nhau qua ảnh và clip.\n- HS phân biệt được sản phẩm hai chiều với sản phẩm ba chiều."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":2,"tiet":2,"bai":"Chủ đề 2: HOA VĂN TRÊN TRANG PHỤC CỦA MỘT SỐ DÂN TỘC (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Biết một số hoa văn được tạo nên từ nét, hình.\n- Chép được một mẫu hoa văn yêu thích và sử dụng hoa văn để trang trí một đồ vật bằng hình thức vẽ, nặn, đắp nổi.\n- Nhận ra vẻ đẹp trên trang phục của một số dân tộc Việt Nam.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nhận ra nét riêng trong hoa văn của từng dân tộc qua ảnh phóng to.","dodung":"- Giáo viên: hình ảnh, video về hoa văn trên trang phục của một số dân tộc (Mông, Chăm…); sản phẩm mĩ thuật được trang trí bằng hoa văn để phân tích trực quan; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem video về lễ hội, trang phục có hoa văn đặc sắc của một số dân tộc và hỏi HS thấy hình ảnh gì.\n- GV khen ngợi và giới thiệu chủ đề.","hs":"- HS xem video, trả lời: lễ hội và trang phục của người dân tộc.\n- HS mở bài học, ghi tên bài."},{"ten":"2. Khám phá","gv":"- GV cho HS quan sát hoa văn trên trang phục dân tộc Mông, Chăm… trong SGK Mĩ thuật 3 (tr.8–10) và hỏi: Hoa văn này có hình gì? Được tạo nên từ những nét nào?\n- GV mở rộng: hoa văn mô phỏng hoa, lá, con vật…, được cách điệu từ hình vuông, tam giác, đường thẳng, đường dích dắc.","hs":"- HS quan sát, gọi tên nét, hình trong hoa văn (nét thẳng, nét cong, hình tam giác, hình thoi…).\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS thực hành chép một mẫu hoa văn yêu thích theo gợi ý: vẽ hình tổng thể rồi vẽ chi tiết từ trái sang phải.\n- GV hướng dẫn dùng hoa văn để trang trí một đồ vật đơn giản.","hs":"- HS chép mẫu hoa văn yêu thích.\n- HS trang trí một đồ vật bằng hình thức vẽ, nặn hoặc đắp nổi."},{"ten":"4. Vận dụng","gv":"- GV tổ chức cho HS thảo luận theo câu hỏi SGK tr.12: hoa văn gồm những yếu tố tạo hình nào, được sắp xếp thế nào (nhắc lại, xen kẽ, đối xứng).\n- GV chốt: yếu tố nét trong hoa văn tạo nên vẻ đẹp trang trí.","hs":"- HS trưng bày sản phẩm, thảo luận và nhận xét sản phẩm của bạn.\n- HS liên hệ hoa văn trang trí trong cuộc sống."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh chụp gần trang phục của các dân tộc Mông, Thái, Ê Đê, Chăm, phóng to đến mức nhìn rõ từng mũi chỉ thêu; mỗi ảnh ghi rõ của dân tộc nào, vùng nào và do bảo tàng hay tác giả nào cung cấp.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS đối chiếu hoa văn của hai dân tộc và chỉ ra điểm khác nhau về hình, về màu.\n⚠ (Miền 4: An toàn) Hoa văn của mỗi dân tộc gắn với văn hoá của cộng đồng ấy nên khi nói phải gọi đúng tên dân tộc, không nhận xét chê bai trang phục của dân tộc khác; ảnh đưa vào bài phải ghi rõ nguồn.","hs":"- HS nhận ra nét riêng trong hoa văn của từng dân tộc qua ảnh phóng to.\n- HS gọi đúng tên dân tộc gắn với hoa văn mình quan sát."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":3,"tiet":3,"bai":"Chủ đề 2: HOA VĂN TRÊN TRANG PHỤC CỦA MỘT SỐ DÂN TỘC (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Biết một số hoa văn được tạo nên từ nét, hình.\n- Chép được một mẫu hoa văn yêu thích và sử dụng hoa văn để trang trí một đồ vật bằng hình thức vẽ, nặn, đắp nổi.\n- Nhận ra vẻ đẹp trên trang phục của một số dân tộc Việt Nam.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: hình ảnh, video về hoa văn trên trang phục của một số dân tộc (Mông, Chăm…); một vài chậu cây, vỏ hộp đã trang trí hoa văn để phân tích trực quan; khuôn in tự tạo từ củ khoai, miếng xốp, lõi giấy vệ sinh bóp dẹp; thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là vỏ hộp sữa hoặc chai nhựa cắt ngắn làm chậu; vật liệu thay thế dễ kiếm: bìa carton cuộn tròn, giấy báo cũ bồi nhiều lớp, vỏ lon giấy, lá cây khô, hột hạt, dây len, vải vụn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS đặt sản phẩm chép hoa văn ở Tiết 1 và đồ dùng, vật liệu lên bàn; GV đi một vòng kiểm tra nhanh, khen nhóm chuẩn bị đủ.\n- GV tổ chức trò chơi Ai tinh mắt: chiếu một mẫu hoa văn trong 5 giây rồi tắt và hỏi: Hoa văn vừa rồi được tạo từ những nét nào? Hình nào được nhắc lại?\n- GV hỏi thêm: Ở Tiết 1 em đã chép mẫu hoa văn của dân tộc nào?\n- GV khen ngợi và dẫn vào bài: hôm nay chúng ta dùng chính mẫu hoa văn ấy để trang trí một chậu cây cho góc lớp.","hs":"- HS đặt sản phẩm Tiết 1 và đồ dùng, vật liệu lên bàn theo hàng ngang cho dễ kiểm tra.\n- HS quan sát nhanh rồi trả lời: có nét thẳng, nét dích dắc; hình tam giác và hình quả trám được nhắc lại nhiều lần.\n- HS nêu tên dân tộc gắn với mẫu hoa văn mình đã chép, ví dụ hoa văn quả trám của dân tộc Mông.\n- HS mở SGK Mĩ thuật 3, ghi tên bài vào vở."},{"ten":"2. Khám phá","gv":"- (8 phút) GV cho HS quan sát hình các bước trang trí chậu cây bằng hoa văn trong SGK và chỉ rõ từng bước: Bước 1 chọn vật liệu làm chậu; Bước 2 vẽ nhẹ bằng bút chì các đường chia thân chậu thành băng ngang; Bước 3 vẽ hoặc in hoa văn vào từng băng theo hình thức nhắc lại, xen kẽ hoặc đối xứng; Bước 4 tô màu và viền nét cho hoa văn rõ; Bước 5 để khô, lau sạch mép, đặt cây hoặc giấy màu vào trong.\n- GV làm mẫu chậm ở bước khó nhất là Bước 3: dùng thước chia đều khoảng cách rồi in liên tiếp một khuôn hoa văn, vừa làm vừa nói kĩ thuật: chấm màu vừa phải, ấn thẳng xuống, nhấc lên dứt khoát thì hình mới sắc nét.\n- GV hỏi: Muốn hoa văn nổi bật trên nền chậu thì chọn màu như thế nào?\n- GV mời 2 HS nhắc lại các bước và nêu lưu ý an toàn: cầm kéo hướng mũi ra ngoài, không tự cắt vỏ hộp cứng bằng dao rọc mà nhờ GV, keo dán chỉ bôi mỏng và không đưa lên miệng.","hs":"- HS quan sát hình trong SGK, chỉ vào từng hình và đọc to tên các bước theo thứ tự từ 1 đến 5.\n- HS theo dõi GV làm mẫu bước in hoa văn, chú ý khoảng cách đều nhau và lực ấn của tay.\n- HS trả lời: nền màu nhạt thì hoa văn màu đậm, hoặc viền thêm nét đậm cho hoa văn nổi lên.\n- 2 HS nhắc lại đủ 5 bước; cả lớp nhắc lại lưu ý an toàn khi dùng kéo và keo dán."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV chia lớp thành nhóm 4, phát vật liệu; HS không có vỏ hộp thì dùng bìa carton cuộn tròn dán lại hoặc giấy báo cũ bồi nhiều lớp để thay cho chậu.\n- GV nêu nhiệm vụ rõ ràng: mỗi HS trang trí một chậu cây hoặc một đồ vật nhỏ (hộp bút, lọ cắm hoa) bằng mẫu hoa văn đã chép ở Tiết 1, trong đó có ít nhất một băng hoa văn nhắc lại và một băng xen kẽ.\n- GV đi từng bàn hỗ trợ HS còn lúng túng: kẻ giúp đường chia băng bằng bút chì mờ, gợi ý HS vẽ thử hoa văn ra giấy nháp trước khi thể hiện lên chậu, nhắc HS đắp nổi bằng đất nặn nếu không có màu.\n- GV báo trước còn 3 phút để HS hoàn thiện, lau tay, cất màu và gom mẩu giấy vụn vào hộp chung của nhóm.","hs":"- HS về nhóm 4, chọn vật liệu phù hợp với điều kiện của mình rồi bày ra bàn.\n- HS thực hiện lần lượt 5 bước đã học: chọn vật liệu, chia băng, vẽ hoặc in hoa văn, tô màu, hoàn thiện sản phẩm.\n- HS vẽ thử ra giấy nháp rồi mới thể hiện lên chậu; trao đổi với bạn cùng nhóm về cách phối màu đậm nhạt.\n- HS hoàn thiện sản phẩm, lau tay, cất đồ dùng và dọn sạch chỗ ngồi trước khi trưng bày."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày theo hình thức phòng tranh mini: kê một dãy bàn sát tường ở góc lớp, mỗi nhóm một khu vực có biển tên chủ đề do nhóm tự viết.\n- GV nêu tiêu chí nhận xét để HS dựa vào đó mà nói: (1) hoa văn rõ nét, đúng mẫu đã chọn; (2) sắp xếp theo nhắc lại, xen kẽ hoặc đối xứng, cân đối quanh chậu; (3) màu sắc hài hoà, có đậm nhạt; (4) sản phẩm sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem một vòng, mỗi em dán một ngôi sao giấy vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV hỏi chốt: Hoa văn trên sản phẩm của em được tạo từ nét, hình, màu nào và sắp xếp theo hình thức nào? GV chốt: hoa văn làm cho đồ vật quen thuộc đẹp hơn và mang nét đẹp văn hoá riêng của mỗi dân tộc.\n- GV dặn dò: giữ sản phẩm ở góc lớp, chuẩn bị màu vẽ, giấy màu, khăn lau cho chủ đề Màu sắc em yêu.","hs":"- HS đặt sản phẩm vào khu vực của nhóm, ghi tên mình vào mẩu giấy nhỏ đặt cạnh sản phẩm.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét trước khi đi xem.\n- HS đi xem phòng tranh mini, dán sao và nói: Mình thích bài này vì hoa văn được in đều và màu rất tươi.\n- HS trả lời câu hỏi chốt, tự đánh giá sản phẩm của mình theo tiêu chí.\n- HS ghi nhớ đồ dùng cần chuẩn bị cho chủ đề tiếp theo."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":4,"tiet":4,"bai":"Chủ đề 3: MÀU SẮC EM YÊU (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Hiểu cách tạo ra màu thứ cấp, phân biệt màu thứ cấp và màu cơ bản.\n- Tạo được sản phẩm mĩ thuật có sự kết hợp các màu đã học; sử dụng được màu đậm, màu nhạt.\n- Thực hiện được một số thao tác cơ bản để làm nên sản phẩm từ giấy màu và màu vẽ.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được màu chủ đạo thay đổi theo ánh sáng qua ba ảnh so sánh.","dodung":"- Giáo viên: tranh, ảnh, đồ vật, tác phẩm mĩ thuật giới thiệu màu sắc; màu và dụng cụ pha màu để làm mẫu; hình ảnh sản phẩm thể hiện màu đậm, màu nhạt; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Viết tên màu sắc; nêu luật chơi, cách chơi.\n- GV khen ngợi và giới thiệu chủ đề.","hs":"- HS tham gia trò chơi theo đội.\n- HS mở bài học, ghi tên bài."},{"ten":"2. Khám phá","gv":"- GV cho HS quan sát màu sắc trong thiên nhiên, trong cuộc sống và trong tranh của hoạ sĩ (SGK tr.14–16).\n- GV làm mẫu pha màu: đỏ + vàng = cam; vàng + xanh lam = xanh lá cây; đỏ + xanh lam = tím, giới thiệu ba màu thứ cấp.","hs":"- HS quan sát, nhận biết màu sắc trong thiên nhiên, cuộc sống, tranh vẽ.\n- HS quan sát cách tạo màu thứ cấp từ ba màu cơ bản; kể tên đồ vật có màu thứ cấp."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS thực hành pha, tô thử ba màu thứ cấp và ghi nhớ tên gọi.\n- GV chốt: ba màu cơ bản pha với nhau tạo ra ba màu thứ cấp.","hs":"- HS thực hành pha/tô màu, đọc tên màu thứ cấp.\n- HS liên hệ màu thứ cấp trong cuộc sống."},{"ten":"4. Vận dụng","gv":"- GV yêu cầu HS nêu lại kiến thức và liên hệ màu sắc với cuộc sống.\n- GV dặn dò bảo quản sản phẩm, chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nêu lại kiến thức, liên hệ thực tế.\n- HS chuẩn bị đồ dùng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh cùng một cảnh chụp vào sáng sớm, giữa trưa và lúc hoàng hôn; ba ảnh đặt cạnh nhau cho HS thấy ánh sáng đổi thì màu của cảnh vật đổi theo, điều chỉ nhận ra khi so sánh trực tiếp nhiều ảnh cùng lúc.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS gọi tên màu chủ đạo của từng thời điểm và đoán cảnh nào cho cảm giác ấm, cảnh nào cho cảm giác lạnh.\n⚠ (Miền 4: An toàn) GV thao tác trên máy, HS quan sát và trả lời tại chỗ; màu trên màn hình thường tươi hơn màu vẽ trên giấy nên HS phải thử màu ra giấy nháp trước khi tô vào bài.","hs":"- HS nêu được màu chủ đạo thay đổi theo ánh sáng qua ba ảnh so sánh.\n- HS phân biệt được cảm giác ấm và cảm giác lạnh của màu."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":5,"tiet":5,"bai":"Chủ đề 3: MÀU SẮC EM YÊU (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Hiểu cách tạo ra màu thứ cấp, phân biệt màu thứ cấp và màu cơ bản.\n- Tạo được sản phẩm mĩ thuật có sự kết hợp các màu đã học; sử dụng được màu đậm, màu nhạt.\n- Thực hiện được một số thao tác cơ bản để làm nên sản phẩm từ giấy màu và màu vẽ.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chỉ và gọi tên được màu cơ bản, màu thứ cấp trên vòng màu.","dodung":"- Giáo viên: tranh, ảnh, đồ vật, tác phẩm mĩ thuật giới thiệu màu sắc; màu và dụng cụ pha màu để làm mẫu; hình ảnh sản phẩm thể hiện màu đậm, màu nhạt; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra kiến thức và đồ dùng của HS ở Tiết 1.\n- GV khen ngợi và giới thiệu nội dung tiết học.","hs":"- HS nêu lại kiến thức Tiết 1, trình bày đồ dùng.\n- HS mở bài học."},{"ten":"2. Khám phá","gv":"- GV gợi ý HS chọn ý tưởng (chân dung, sinh hoạt, phong cảnh, con vật, đồ vật…) và chất liệu (màu vẽ, xé dán, đất nặn) để thể hiện sản phẩm.\n- GV cho HS xem sản phẩm tham khảo SGK tr.18.","hs":"- HS chọn ý tưởng và chất liệu yêu thích.\n- HS quan sát, nhận xét sản phẩm tham khảo."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS thực hành tạo một sản phẩm mĩ thuật 2D hoặc 3D có sử dụng các màu đã học.\n- GV quan sát, hỗ trợ HS hoàn thiện.","hs":"- HS thực hành vẽ, xé dán hoặc nặn tạo sản phẩm có màu cơ bản và màu thứ cấp.\n- HS hoàn thiện sản phẩm trên lớp."},{"ten":"4. Vận dụng","gv":"- GV cho HS thảo luận SGK tr.19: sản phẩm có những hình ảnh, màu sắc gì; chỉ ra màu cơ bản, màu thứ cấp.\n- GV nhận xét, động viên.","hs":"- HS trưng bày, chia sẻ về sản phẩm; chỉ ra các màu đã dùng.\n- HS nhận xét sản phẩm của bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu vòng thuyết màu và bấm cho hai màu cơ bản trộn dần vào nhau, màu thứ cấp hiện ra ở giữa; kéo tỉ lệ qua lại để HS thấy có rất nhiều sắc độ trung gian giữa hai màu.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chỉ trên vòng màu vị trí ba màu cơ bản và ba màu thứ cấp, đọc tên từng màu.\n⚠ (Miền 4: An toàn) GV điều khiển mô phỏng; xem xong HS phải pha màu thật bằng bút lông và bảng pha để tự tay kiểm chứng, không thay việc pha màu thật bằng màn hình.","hs":"- HS chỉ và gọi tên được màu cơ bản, màu thứ cấp trên vòng màu.\n- HS pha lại màu thứ cấp bằng màu vẽ thật và đối chiếu kết quả."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":6,"tiet":6,"bai":"Chủ đề 3: MÀU SẮC EM YÊU (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Hiểu cách tạo ra màu thứ cấp, phân biệt màu thứ cấp và màu cơ bản.\n- Tạo được sản phẩm mĩ thuật có sự kết hợp các màu đã học; sử dụng được màu đậm, màu nhạt.\n- Thực hiện được một số thao tác cơ bản để làm nên sản phẩm từ giấy màu và màu vẽ.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: tranh, ảnh, đồ vật, tác phẩm mĩ thuật giới thiệu màu sắc; màu và dụng cụ pha màu để làm mẫu; một khung ảnh mẫu đã hoàn thiện và một khung ảnh làm dở để phân tích trực quan; hình ảnh sản phẩm thể hiện màu đậm, màu nhạt; thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là bìa cứng làm khung; vật liệu thay thế dễ kiếm: bìa carton hộp bánh, giấy báo cũ, vỏ hộp sữa cắt phẳng, lá cây khô, hột hạt, dây len, vải vụn để trang trí viền khung.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS bày sản phẩm pha màu ở Tiết 2 và đồ dùng lên bàn, kiểm tra nhanh xem nhóm nào còn thiếu kéo, keo, giấy màu để mượn bổ sung.\n- GV tổ chức trò chơi Gọi tên màu: GV giơ một mảnh giấy màu cam, màu tím, màu xanh lá và hỏi: Đây là màu cơ bản hay màu thứ cấp? Màu này pha từ hai màu nào?\n- GV hỏi tiếp: Muốn có màu nhạt hơn thì làm thế nào?\n- GV khen ngợi và giới thiệu nhiệm vụ tiết học: cả nhóm cùng làm một khung ảnh chung để treo ở lớp.","hs":"- HS bày sản phẩm Tiết 2 và đồ dùng lên bàn, báo cáo nhanh phần còn thiếu.\n- HS trả lời: cam là màu thứ cấp, pha từ đỏ và vàng; tím pha từ đỏ và xanh lam; xanh lá pha từ vàng và xanh lam.\n- HS trả lời: pha thêm màu trắng hoặc pha loãng với nước thì màu nhạt đi.\n- HS lắng nghe nhiệm vụ, mở SGK và ghi tên bài."},{"ten":"2. Khám phá","gv":"- (8 phút) GV cho HS quan sát các bước thiết kế, trang trí khung ảnh chung của nhóm trong SGK tr.20 và nêu rõ: Bước 1 chọn vật liệu và cắt hai tấm bìa bằng nhau; Bước 2 khoét ô giữa của tấm trên làm cửa sổ khung; Bước 3 chọn hình trang trí (hoa, lá, ngôi sao, hình học) và cắt từ giấy màu; Bước 4 sắp xếp thử rồi mới dán viền khung; Bước 5 luồn dây len làm quai treo và dán tấm sau chừa một khe để lồng ảnh.\n- GV làm mẫu chậm ở Bước 2 và Bước 4: dùng bút chì kẻ ô trước khi khoét, sắp hình ra ngoài khung để ngắm bố cục rồi mới bôi keo, bôi keo mỏng ở mặt sau hình.\n- GV lưu ý kĩ thuật phối màu: khung nên dùng màu nhạt làm nền, hình trang trí dùng màu đậm hơn để nổi bật; nếu dùng hai màu thứ cấp cạnh nhau thì thêm một mảng màu trắng ngăn cách cho đỡ rối.\n- GV hỏi: Nếu nhóm em không có bìa cứng thì thay bằng gì? GV chốt cách thay thế và nhắc an toàn: chỉ GV dùng dao rọc để khoét ô, HS dùng kéo.","hs":"- HS quan sát SGK tr.20, đọc to tên 5 bước và chỉ vào hình minh hoạ tương ứng.\n- HS theo dõi GV làm mẫu, chú ý cách kẻ ô trước khi cắt và cách ướm thử hình trước khi dán.\n- HS nhắc lại lưu ý kĩ thuật: nền nhạt, hình đậm; bôi keo mỏng ở mặt sau; ép nhẹ cho phẳng.\n- HS trả lời: có thể dùng bìa carton hộp bánh, vỏ hộp sữa cắt phẳng hoặc giấy báo cũ bồi nhiều lớp; ghi nhớ quy định an toàn khi cắt."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV cho HS làm cá nhân hoặc theo nhóm 2, 4, 6 tuỳ điều kiện; GV phân công trong nhóm để ai cũng có việc: một bạn cắt bìa, một bạn cắt hình trang trí, một bạn sắp xếp, một bạn dán và làm quai treo.\n- GV nêu yêu cầu sản phẩm: khung ảnh có ít nhất ba màu đã học, trong đó thấy rõ một cặp màu đậm và màu nhạt; hình trang trí sắp xếp cân đối quanh khung.\n- GV quan sát, hỗ trợ những nhóm khó khăn: cắt giúp phần bìa cứng, gợi ý HS nếu keo chưa dính thì kẹp bằng kẹp giấy chờ khô, nếu hình bị lệch thì gỡ nhẹ khi keo còn ướt.\n- GV nhắc còn 3 phút cuối để hoàn thiện quai treo, lau tay, gom giấy vụn và cất kéo đúng chỗ.","hs":"- HS về nhóm, nhận nhiệm vụ được phân công và cùng thống nhất màu chủ đạo cho khung ảnh.\n- HS thực hiện lần lượt các bước: cắt bìa, khoét ô, cắt hình trang trí, sắp xếp thử, dán và luồn dây len.\n- HS kiểm tra sản phẩm theo yêu cầu: đủ ba màu, có đậm nhạt, hình sắp xếp cân đối quanh khung.\n- HS hoàn thiện quai treo, lau tay, gom giấy vụn và cất kéo, keo vào hộp đồ dùng."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày bằng cách treo các khung ảnh lên một sợi dây căng ngang góc lớp bằng kẹp giấy, tạo thành phòng tranh mini của lớp.\n- GV nêu tiêu chí nhận xét: (1) khung chắc chắn, cắt dán sạch sẽ; (2) hình trang trí sắp xếp cân đối quanh khung; (3) màu sắc hài hoà, thấy rõ màu đậm và màu nhạt; (4) nhóm có ý tưởng riêng, biết đặt tên cho khung ảnh.\n- GV cho HS đi xem, mỗi em dán một ngôi sao vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV hỏi: Nhóm em đã dùng những màu nào để trang trí, màu nào là màu thứ cấp? GV chốt: kết hợp màu cơ bản với màu thứ cấp và biết dùng đậm nhạt sẽ làm sản phẩm đẹp hơn.\n- GV dặn dò chuẩn bị chủ đề Vẻ đẹp của khối: đất nặn, dây thép mềm hoặc dây kẽm nhung, vỏ hộp nhỏ, giấy báo cũ.","hs":"- HS cùng nhóm treo khung ảnh lên dây, đặt biển tên nhóm bên cạnh.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì màu nền nhạt làm hình hoa nổi lên rất rõ.\n- HS trả lời câu hỏi chốt, gọi đúng tên màu cơ bản và màu thứ cấp trên sản phẩm nhóm mình.\n- HS ghi nhớ vật liệu cần chuẩn bị cho chủ đề sau."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":7,"tiet":7,"bai":"Chủ đề 4: VẺ ĐẸP CỦA KHỐI (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Hiểu một số hình thức biểu hiện của khối (cứng – mềm, đặc – rỗng, tĩnh – động).\n- Tạo được sản phẩm mĩ thuật 3D cho cảm giác khác nhau về khối và tạo cảm giác về sự chuyển động.\n- Biết sử dụng đất nặn, dây thép, giấy, vật liệu sẵn có trong thực hành, sáng tạo sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nhận ra khối lồi, khối lõm và bóng đổ khi xem tượng chụp từ nhiều phía.","dodung":"- Giáo viên: hình ảnh, clip giới thiệu một số tượng, tác phẩm điêu khắc; sản phẩm mĩ thuật 3D có biểu hiện khối để phân tích trực quan; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Thi kể tên các khối; nêu luật chơi, cách chơi.\n- GV khen ngợi và giới thiệu chủ đề.","hs":"- HS tham gia trò chơi theo đội.\n- HS mở bài học, ghi tên bài."},{"ten":"2. Khám phá","gv":"- GV cho HS quan sát các cặp khối tương phản (SGK tr.22): khối cứng – mềm, đặc – rỗng, tĩnh – động và gọi tên biểu hiện.\n- GV cho HS quan sát biểu hiện của khối trên sản phẩm mĩ thuật (tr.23) và phân tích.","hs":"- HS quan sát, gọi tên các cặp khối tương phản.\n- HS phân tích biểu hiện của khối trên sản phẩm."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV tổ chức cho HS vẽ một số khối em yêu thích (khối tròn, khối dẹt, khối động, khối tĩnh…).\n- GV quan sát, giúp đỡ HS hoàn thành.","hs":"- HS thực hành vẽ một số khối yêu thích.\n- HS hoàn thành bài tập."},{"ten":"4. Vận dụng","gv":"- GV yêu cầu HS nêu lại kiến thức về biểu hiện của khối và liên hệ với đồ vật trong cuộc sống.\n- GV dặn dò bảo quản sản phẩm, chuẩn bị đồ dùng.","hs":"- HS nêu lại kiến thức, liên hệ thực tế.\n- HS chuẩn bị đồ dùng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh một pho tượng chụp từ nhiều phía và cho chuyển ảnh liên tục để HS thấy khối lồi, khối lõm, chỗ nhận sáng, chỗ đổ bóng thay đổi ra sao khi đổi hướng nhìn; đứng trước tượng thật cũng phải đi vòng quanh mới thấy được điều này.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chỉ trên màn hình chỗ khối nhô ra, chỗ khối lõm vào và nói vì sao mình nhận ra.\n⚠ (Miền 4: An toàn) Ảnh tượng lấy từ trang của bảo tàng, GV nêu rõ tên tác phẩm và nơi lưu giữ; HS xem để học, không tải ảnh về máy riêng.","hs":"- HS nhận ra khối lồi, khối lõm và bóng đổ khi xem tượng chụp từ nhiều phía.\n- HS nêu được vì sao ánh sáng giúp nhìn rõ khối."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":8,"tiet":8,"bai":"Chủ đề 4: VẺ ĐẸP CỦA KHỐI (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Hiểu một số hình thức biểu hiện của khối (cứng – mềm, đặc – rỗng, tĩnh – động).\n- Tạo được sản phẩm mĩ thuật 3D cho cảm giác khác nhau về khối và tạo cảm giác về sự chuyển động.\n- Biết sử dụng đất nặn, dây thép, giấy, vật liệu sẵn có trong thực hành, sáng tạo sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: hình ảnh, clip giới thiệu một số tượng, tác phẩm điêu khắc; hai sản phẩm mĩ thuật 3D làm mẫu, một sản phẩm cho cảm giác tĩnh và một sản phẩm cho cảm giác động để phân tích trực quan; bảng nặn, dao nhựa, tăm tre; thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là đất nặn và dây thép mềm; vật liệu thay thế dễ kiếm: đất sét địa phương, bột mì trộn muối, giấy báo cũ vò chặt bọc hồ, bìa carton, vỏ hộp sữa, hột hạt, dây len, lá cây khô.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS bày sản phẩm và đồ dùng của Tiết 1 lên bảng nặn, kiểm tra nhanh xem HS nào chưa có đất nặn để bố trí dùng vật liệu thay thế.\n- GV tổ chức trò chơi Đoán cảm giác: GV giơ lần lượt một hòn sỏi, một cuộn len và một chiếc lá và hỏi: Vật nào cho cảm giác khối cứng, vật nào cho cảm giác khối mềm?\n- GV hỏi tiếp: Ở Tiết 1 em đã tìm được những biểu hiện nào của khối?\n- GV khen ngợi và giới thiệu nội dung tiết học: tạo một sản phẩm 3D thể hiện biểu hiện khối mà em thích.","hs":"- HS bày sản phẩm Tiết 1 và đồ dùng, vật liệu lên bàn, báo cáo phần còn thiếu.\n- HS sờ, quan sát và trả lời: hòn sỏi cho cảm giác cứng và đặc, cuộn len cho cảm giác mềm, chiếc lá mỏng và nhẹ.\n- HS nhắc lại các biểu hiện của khối: cứng – mềm, đặc – rỗng, tĩnh – động.\n- HS lắng nghe nhiệm vụ, mở SGK và ghi tên bài."},{"ten":"2. Khám phá","gv":"- (8 phút) GV gợi ý HS liên tưởng tới một biểu hiện của khối yêu thích bằng câu hỏi: Em muốn nặn con vật đang chạy hay đang ngủ? Muốn khối trông cứng chắc hay mềm mại?\n- GV thị phạm chậm bốn kĩ thuật cơ bản trên đất nặn: (1) vê tròn và lăn dài tạo khối cơ bản; (2) ấn dẹt hoặc bóp nhẹ để tạo khối mềm; (3) khoét lõm bằng đầu dao nhựa để tạo khối rỗng; (4) đắp thêm chi tiết và uốn nghiêng thân, chân để tạo cảm giác chuyển động.\n- GV nhấn mạnh bước khó là bước 4: muốn sản phẩm có cảm giác động thì các bộ phận phải nghiêng theo cùng một hướng, có thể luồn lõi dây thép bên trong để giữ dáng.\n- GV nêu cách thay thế: HS không có đất nặn thì vò giấy báo cũ thành lõi, quấn giấy dán hồ bên ngoài rồi để khô; nhắc an toàn: dây thép cắt xong phải gập đầu nhọn, không đưa đất nặn lên miệng, rửa tay sau khi làm.","hs":"- HS suy nghĩ và nói ý tưởng của mình: nặn con mèo đang ngủ cho cảm giác tĩnh, nặn con cá đang bơi cho cảm giác động.\n- HS quan sát GV thị phạm, gọi tên bốn kĩ thuật: vê tròn, ấn dẹt, khoét lõm, đắp thêm và uốn dáng.\n- HS nhắc lại bí quyết tạo cảm giác chuyển động: các bộ phận nghiêng cùng hướng, thân hơi cong.\n- HS nêu vật liệu thay thế mình sẽ dùng và nhắc lại quy định an toàn khi dùng dây thép, đất nặn."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV cho HS thực hành theo các bước đã thị phạm: Bước 1 chọn hình định tạo; Bước 2 nặn khối lớn của thân trước; Bước 3 gắn các khối nhỏ (đầu, chân, đuôi); Bước 4 tạo chi tiết bằng khoét, ấn, vạch nét; Bước 5 chỉnh dáng và đặt lên đế cho vững.\n- GV lưu ý kĩ thuật gắn: miết kĩ chỗ nối cho liền khối, nếu chi tiết nhỏ hay rơi thì cắm một đoạn tăm tre bên trong làm trụ.\n- GV đi từng bàn hỗ trợ HS còn lúng túng, làm mẫu lại riêng cho HS chưa gắn được đầu vào thân; gợi ý HS khá thêm hoạ tiết vạch trên bề mặt để khối thêm sinh động.\n- GV nhắc còn 3 phút cuối để đặt tên sản phẩm, lau bảng nặn, rửa tay và cất đất thừa vào hộp kín.","hs":"- HS thực hành lần lượt 5 bước, bắt đầu từ khối thân rồi mới đến các khối nhỏ.\n- HS miết kĩ chỗ nối, dùng tăm tre làm trụ cho chi tiết nhỏ khỏi rơi.\n- HS chỉnh dáng nghiêng của thân và chân để sản phẩm có cảm giác đang chuyển động, thêm nét vạch trang trí.\n- HS đặt tên sản phẩm, lau bảng nặn, rửa tay và cất đất thừa vào hộp kín."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS đặt sản phẩm lên bảng nhóm chia thành hai khu: khu Khối tĩnh và khu Khối động, tạo thành một triển lãm tượng nhỏ ở góc lớp.\n- GV nêu tiêu chí nhận xét sản phẩm: (1) thấy rõ một biểu hiện của khối; (2) các khối gắn chắc, liền mạch, đứng vững; (3) có chi tiết trang trí và dáng sinh động; (4) sản phẩm sạch sẽ, có ý tưởng riêng.\n- GV tổ chức thảo luận theo câu hỏi SGK tr.25: Sản phẩm có biểu hiện nào của khối? Em thích sản phẩm nào nhất và vì sao?\n- GV cho HS đi xem, dán sao vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì... GV chốt: có nhiều hình thức biểu hiện của khối, mỗi biểu hiện đem lại một cảm nhận khác nhau.\n- GV dặn dò chuẩn bị cho chủ đề sau: nhặt và giữ lại lá cây khô, sỏi nhỏ, vỏ cây, hột hạt, vỏ hộp sạch.","hs":"- HS đặt sản phẩm vào đúng khu Khối tĩnh hoặc khu Khối động trên bảng nhóm, ghi tên vào mẩu giấy nhỏ.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét trước khi đi xem.\n- HS trưng bày, chia sẻ về biểu hiện khối trên sản phẩm của mình và trả lời câu hỏi SGK.\n- HS đi xem, dán sao và nói: Mình thích bài này vì con cá trông như đang bơi.\n- HS nhận xét sản phẩm của bạn theo tiêu chí và ghi nhớ vật liệu cần chuẩn bị."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":9,"tiet":9,"bai":"Chủ đề 4: VẺ ĐẸP CỦA KHỐI (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Hiểu một số hình thức biểu hiện của khối (cứng – mềm, đặc – rỗng, tĩnh – động).\n- Tạo được sản phẩm mĩ thuật 3D cho cảm giác khác nhau về khối và tạo cảm giác về sự chuyển động.\n- Biết sử dụng đất nặn, dây thép, giấy, vật liệu sẵn có trong thực hành, sáng tạo sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chỉ ra được các dấu hiệu tạo cảm giác chuyển động qua clip quay chậm.","dodung":"- Giáo viên: hình ảnh, clip giới thiệu một số tượng, tác phẩm điêu khắc; sản phẩm mĩ thuật 3D có biểu hiện khối để phân tích trực quan; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm và đồ dùng của HS ở Tiết 2.\n- GV khen ngợi và giới thiệu nội dung tiết học.","hs":"- HS trưng bày sản phẩm Tiết 2 và đồ dùng.\n- HS mở bài học."},{"ten":"2. Khám phá","gv":"- GV cho HS thưởng thức hai tác phẩm điêu khắc của nhà điêu khắc An-be-tô Gia-cô-mét-ti (SGK tr.25–27) và phân tích yếu tố tạo cảm giác chuyển động.\n- GV giới thiệu các bước tạo biểu đạt hành động cho sản phẩm.","hs":"- HS xem, phân tích yếu tố tạo cảm giác chuyển động trên tác phẩm.\n- HS tham khảo các bước thực hiện."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS thực hành tạo một sản phẩm mĩ thuật 3D từ vật liệu sẵn có tạo cảm giác về sự chuyển động.\n- GV quan sát, hỗ trợ HS.","hs":"- HS thực hành tạo sản phẩm 3D có cảm giác chuyển động.\n- HS hoàn thiện sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trưng bày, nhận xét cuối chủ đề: sản phẩm làm từ vật liệu gì, có cảm giác chuyển động không.\n- GV dặn dò chuẩn bị chủ đề Một số vật liệu sử dụng trong thực hành, sáng tạo mĩ thuật.","hs":"- HS trưng bày, giới thiệu, chia sẻ cảm nhận.\n- HS cùng nhận xét, đánh giá."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu clip quay chậm một tác phẩm điêu khắc động và một vận động viên đang chạy; xem chậm giúp HS thấy tư thế nghiêng, tay chân đưa về phía trước tạo ra cảm giác chuyển động, còn mắt thường nhìn lúc chạy nhanh không kịp bắt được.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dừng hình ở một tư thế để HS mô tả lại: đầu nghiêng phía nào, chân trước chân sau ra sao.\n⚠ (Miền 4: An toàn) GV điều khiển việc dừng và tua clip; HS quan sát rồi bắt chước tư thế ngay tại chỗ, không chạy nhảy trong lớp khi làm mẫu.","hs":"- HS chỉ ra được các dấu hiệu tạo cảm giác chuyển động qua clip quay chậm.\n- HS mô tả và làm lại được một tư thế đã dừng hình."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":10,"tiet":10,"bai":"Chủ đề 5: MỘT SỐ VẬT LIỆU SỬ DỤNG TRONG THỰC HÀNH, SÁNG TẠO MĨ THUẬT (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Biết được sự đa dạng của vật liệu sử dụng trong thực hành, sáng tạo mĩ thuật.\n- Cảm nhận được chất cảm (bề mặt) khác nhau của vật liệu; kết hợp nhiều vật liệu tạo sản phẩm.\n- Biết sử dụng vật liệu sẵn có, vật liệu tái sử dụng để làm đồ lưu niệm, sản phẩm mĩ thuật.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS gọi tên được vật liệu qua ảnh chụp gần bề mặt.","dodung":"- Giáo viên: hình ảnh, clip giới thiệu vật liệu từ thiên nhiên và trong cuộc sống; sản phẩm mĩ thuật sử dụng nhiều vật liệu; hộp kín đựng một số vật liệu để HS cảm nhận; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem video, tranh ảnh về tác phẩm mĩ thuật sử dụng vật liệu sẵn có trong thiên nhiên, tái chế và hỏi: Nhà em có vật liệu tái chế nào có thể làm sản phẩm mĩ thuật?\n- GV khen ngợi và giới thiệu chủ đề.","hs":"- HS xem, nhận biết vật liệu có thể tạo sản phẩm mĩ thuật; trả lời câu hỏi.\n- HS mở bài học, ghi tên bài."},{"ten":"2. Khám phá","gv":"- GV đặt một số vật liệu (vỏ cây, lá cây, cánh hoa, bông vải, vỏ hộp…) vào hộp kín cho HS sờ và mô tả cảm giác (chất cảm).\n- GV cho HS quan sát sản phẩm sử dụng nhiều vật liệu (SGK tr.30); chốt: mỗi vật liệu cho một cảm giác khác nhau.","hs":"- HS sờ và mô tả cảm giác về vật liệu (sần sùi, mịn, mềm, cứng…).\n- HS quan sát, tìm hiểu sản phẩm sử dụng nhiều vật liệu."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV tổ chức cho HS thi kể các vật liệu có trong tự nhiên, gia đình, cuộc sống theo cá nhân/nhóm.\n- GV khen ngợi, chốt về việc chọn và kết hợp vật liệu.","hs":"- HS thi kể tên các vật liệu quen thuộc.\n- HS liên hệ vật liệu có thể dùng làm sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV yêu cầu HS nêu lại kiến thức và liên hệ ý thức sưu tầm, tái sử dụng vật liệu.\n- GV dặn dò chuẩn bị vật liệu cho tiết sau.","hs":"- HS nêu lại kiến thức, liên hệ thực tế.\n- HS chuẩn bị vật liệu."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh chụp gần bề mặt các vật liệu: giấy báo, vải vụn, len, lá khô, vỏ ốc, nhựa, đất nặn; ảnh phóng to cho thấy vân, độ nhám, độ bóng của từng loại mà nhìn qua bằng mắt thường khó phân biệt.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS đoán tên vật liệu qua ảnh phóng to rồi kiểm tra bằng cách sờ mẫu vật thật GV đưa cho từng bàn.\n⚠ (Miền 4: An toàn) GV chuẩn bị mẫu vật sạch, không sắc cạnh; HS rửa tay sau khi cầm vật liệu; ảnh chỉ để nhận biết, không thay được việc sờ và cảm nhận bằng tay.","hs":"- HS gọi tên được vật liệu qua ảnh chụp gần bề mặt.\n- HS đối chiếu ảnh với mẫu vật thật và nêu đặc điểm của vật liệu."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":11,"tiet":11,"bai":"Chủ đề 5: MỘT SỐ VẬT LIỆU SỬ DỤNG TRONG THỰC HÀNH, SÁNG TẠO MĨ THUẬT (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Biết được sự đa dạng của vật liệu sử dụng trong thực hành, sáng tạo mĩ thuật.\n- Cảm nhận được chất cảm (bề mặt) khác nhau của vật liệu; kết hợp nhiều vật liệu tạo sản phẩm.\n- Biết sử dụng vật liệu sẵn có, vật liệu tái sử dụng để làm đồ lưu niệm, sản phẩm mĩ thuật.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: hình ảnh, clip giới thiệu vật liệu từ thiên nhiên và trong cuộc sống; sản phẩm mĩ thuật sử dụng nhiều vật liệu để phân tích trực quan; hộp kín đựng một số vật liệu để HS sờ và đoán; con lăn hoặc thìa nhựa để miết khi in lá; giấy lót bàn, khăn lau; thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là lá cây có gân nổi, sỏi nhỏ, hột hạt; vật liệu thay thế dễ kiếm: giấy báo cũ, bìa carton, vỏ hộp, vỏ trứng rửa sạch, vỏ cây khô, dây len, vải vụn, cúc áo cũ.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra nhanh vật liệu HS mang theo, xếp chung vào khay của nhóm và bổ sung cho HS còn thiếu từ khay dự trữ của lớp.\n- GV tổ chức trò chơi Chiếc hộp bí mật: mời 3 HS lần lượt thò tay vào hộp kín, sờ và đoán vật liệu, sau đó tả lại bề mặt.\n- GV hỏi: Vật liệu nào nhẵn, vật liệu nào sần sùi, vật liệu nào mềm?\n- GV khen ngợi và giới thiệu nội dung tiết học: dùng chính những vật liệu ấy để làm một sản phẩm mĩ thuật yêu thích.","hs":"- HS xếp vật liệu mang theo vào khay chung của nhóm, nêu tên từng loại.\n- 3 HS chơi trò Chiếc hộp bí mật, sờ và đoán: đây là hòn sỏi vì tròn và nhẵn, đây là lá cây vì mỏng và có gân nổi.\n- HS trả lời: sỏi và vỏ hộp nhẵn, vỏ cây và lá khô sần sùi, dây len và vải vụn mềm.\n- HS nhắc lại kiến thức Tiết 1 về chất cảm của vật liệu, mở SGK và ghi tên bài."},{"ten":"2. Khám phá","gv":"- (8 phút) GV gợi ý HS lên ý tưởng bằng câu hỏi: Em định làm bức tranh gì? Vật liệu nào hợp để làm thân cây, tán lá, mặt đất?\n- GV cho HS xem phần tham khảo SGK tr.31 và thị phạm chậm kĩ thuật in lá cây theo 4 bước: Bước 1 chọn lá có gân nổi rõ, lau khô; Bước 2 quét màu đều lên mặt có gân của lá, không quét quá nhiều nước; Bước 3 úp mặt có màu xuống giấy, đặt một tờ giấy lót lên trên rồi miết đều từ giữa ra ngoài; Bước 4 nhấc lá lên theo chiều thẳng đứng, để khô rồi vẽ thêm nét hoặc gắn vật liệu khác.\n- GV lưu ý kĩ thuật hay hỏng: màu loãng quá thì hình bị nhoè, màu đặc quá thì mất gân lá; miết không đều thì hình bị mất một góc.\n- GV hướng dẫn cách gắn vật liệu: keo bôi ở mặt sau vật liệu, vật nặng như sỏi thì bôi keo dày hơn và ấn giữ khoảng 10 giây; nhắc an toàn: dùng kéo cẩn thận, không ngậm hột hạt, lau tay sau khi dùng keo.","hs":"- HS nêu ý tưởng và chọn vật liệu: dùng lá khô làm tán cây, dùng vỏ cây làm thân, dùng sỏi nhỏ làm mặt đất.\n- HS vẽ phác hình bố cục ra giấy, xác định chỗ đặt hình chính và hình phụ.\n- HS quan sát GV thị phạm và nhắc lại 4 bước in lá cây theo đúng thứ tự.\n- HS nêu lỗi cần tránh khi in và nhắc lại cách bôi keo, quy định an toàn khi dùng kéo, hột hạt."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV cho HS thực hành theo trình tự: Bước 1 phác bố cục; Bước 2 in màu các mảng lớn; Bước 3 gắn ghép vật liệu vào hình chính; Bước 4 thêm chi tiết và nền; Bước 5 đặt tên sản phẩm.\n- GV nhắc kĩ thuật sắp xếp bố cục: hình chính đặt to hơn và gần giữa tranh, hình phụ nhỏ hơn đặt xung quanh; chừa khoảng trống cho tranh thoáng.\n- GV đi từng bàn hỗ trợ, làm mẫu lại thao tác miết lá cho HS in bị nhoè; gợi ý HS thiếu vật liệu thiên nhiên thì xé giấy báo cũ vò nhàu tạo chất cảm sần hoặc dùng vỏ trứng dán vụn.\n- GV nhắc còn 3 phút cuối để hoàn thiện, thu gom vật liệu thừa vào khay, lau bàn và rửa tay.","hs":"- HS thực hành lần lượt 5 bước, in các mảng lớn trước rồi mới gắn vật liệu.\n- HS sắp xếp hình chính to và rõ ở giữa, hình phụ nhỏ hơn ở xung quanh.\n- HS phối hợp nhiều vật liệu để tạo chất cảm khác nhau trên cùng một sản phẩm.\n- HS hoàn thiện, đặt tên sản phẩm, thu gom vật liệu thừa, lau bàn và rửa tay."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày trên bảng nhóm theo chủ đề: bảng Vật liệu thiên nhiên và bảng Vật liệu tái sử dụng, dán sản phẩm bằng băng dính giấy.\n- GV nêu tiêu chí nhận xét: (1) kết hợp được ít nhất hai loại vật liệu; (2) hình chính rõ, bố cục cân đối; (3) màu sắc hài hoà, có đậm nhạt; (4) sản phẩm chắc chắn, sạch sẽ, có ý tưởng riêng.\n- GV cho HS thảo luận theo câu hỏi: Sản phẩm của em dùng vật liệu gì, bề mặt cho cảm giác thế nào? Em thích sản phẩm nào nhất?\n- GV cho HS đi xem, dán sao và nói theo mẫu: Mình thích bài này vì... GV nhận xét, động viên và chốt: cùng một hình ảnh nhưng đổi vật liệu sẽ cho cảm nhận khác nhau.\n- GV dặn dò chuẩn bị chủ đề Biết ơn thầy cô: giấy vẽ, màu, ảnh hoặc hình ảnh về hoạt động của thầy cô.","hs":"- HS dán sản phẩm lên đúng bảng nhóm theo loại vật liệu đã dùng.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS trưng bày và chia sẻ: em dùng lá khô và vỏ cây, bề mặt sần sùi cho cảm giác giống cây thật.\n- HS đi xem, dán sao và nói: Mình thích bài này vì bạn ghép vỏ trứng làm mây trông rất lạ.\n- HS nhận xét sản phẩm của bạn theo tiêu chí và ghi nhớ đồ dùng cần chuẩn bị."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":12,"tiet":12,"bai":"Chủ đề 5: MỘT SỐ VẬT LIỆU SỬ DỤNG TRONG THỰC HÀNH, SÁNG TẠO MĨ THUẬT (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Biết được sự đa dạng của vật liệu sử dụng trong thực hành, sáng tạo mĩ thuật.\n- Cảm nhận được chất cảm (bề mặt) khác nhau của vật liệu; kết hợp nhiều vật liệu tạo sản phẩm.\n- Biết sử dụng vật liệu sẵn có, vật liệu tái sử dụng để làm đồ lưu niệm, sản phẩm mĩ thuật.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS lập được trang giới thiệu sản phẩm có ảnh, vật liệu và tên tác giả.","dodung":"- Giáo viên: hình ảnh, clip giới thiệu vật liệu từ thiên nhiên và trong cuộc sống; sản phẩm mĩ thuật sử dụng nhiều vật liệu; hộp kín đựng một số vật liệu để HS cảm nhận; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm và vật liệu của HS ở Tiết 2.\n- GV khen ngợi và giới thiệu nội dung tiết học.","hs":"- HS trưng bày sản phẩm Tiết 2 và vật liệu.\n- HS mở bài học."},{"ten":"2. Khám phá","gv":"- GV hướng dẫn HS làm một đồ lưu niệm từ vật liệu sẵn có, kết hợp các vật liệu cho chất cảm tương phản.\n- GV lưu ý an toàn khi dùng kéo, keo.","hs":"- HS quan sát, tiếp thu cách làm đồ lưu niệm.\n- HS chuẩn bị vật liệu phù hợp."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS thực hành làm đồ lưu niệm từ vật liệu kết hợp.\n- GV quan sát, hỗ trợ HS hoàn thành.","hs":"- HS thực hành làm đồ lưu niệm.\n- HS hoàn thiện sản phẩm trên lớp."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trưng bày, nhận xét cuối chủ đề.\n- GV dặn dò chuẩn bị chủ đề Biết ơn thầy cô.","hs":"- HS trưng bày, giới thiệu, chia sẻ cảm nhận.\n- HS cùng nhận xét, đánh giá."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp đồ lưu niệm của từng nhóm và ghép thành một trang giới thiệu có ảnh, tên sản phẩm, vật liệu đã dùng và tên nhóm tác giả, trình bày giống một tờ giới thiệu sản phẩm thật.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) Các nhóm đọc trang giới thiệu của nhóm bạn và đặt cho nhóm bạn một câu hỏi về cách làm.\n⚠ (Miền 4: An toàn) Ghi đúng tên nhóm làm ra sản phẩm dưới mỗi ảnh; nếu nhóm học cách làm từ một mẫu tìm được thì phải ghi rõ đã tham khảo từ đâu.","hs":"- HS lập được trang giới thiệu sản phẩm có ảnh, vật liệu và tên tác giả.\n- HS đặt được câu hỏi cho nhóm bạn về cách làm sản phẩm."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":13,"tiet":13,"bai":"Chủ đề 6: BIẾT ƠN THẦY CÔ (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp, ý nghĩa của hình ảnh thầy cô và ngày Nhà giáo Việt Nam 20-11.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, bưu thiếp, sản phẩm 3D) về chủ đề thầy cô.\n- Biết sắp xếp hình, màu và trang trí để thể hiện tình cảm biết ơn thầy cô.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS kể được nội dung tranh, ảnh về nhà giáo và nêu cảm nhận.","dodung":"- Giáo viên: hình ảnh, clip về hoạt động của thầy cô, ngày Nhà giáo Việt Nam; tranh, bưu thiếp, sản phẩm mĩ thuật về chủ đề thầy cô để làm mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS nghe/hát một bài hát về thầy cô và hỏi cảm nhận.\n- GV khen ngợi và giới thiệu chủ đề nhân ngày Nhà giáo Việt Nam 20-11.","hs":"- HS nghe/hát, chia sẻ cảm nhận về thầy cô.\n- HS mở bài học, ghi tên bài."},{"ten":"2. Khám phá","gv":"- GV cho HS quan sát hình ảnh về hoạt động của thầy cô và một số sản phẩm mĩ thuật về chủ đề thầy cô trong SGK.\n- GV gợi ý HS nhớ lại hình ảnh, kỉ niệm với thầy cô.","hs":"- HS quan sát, kể về hoạt động và tình cảm với thầy cô.\n- HS nêu ý tưởng sản phẩm muốn thể hiện."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV hướng dẫn HS phác ý tưởng và cách sắp xếp hình ảnh thầy cô, học sinh, bối cảnh lớp học.\n- GV cho HS vẽ phác bố cục.","hs":"- HS phác ý tưởng và bố cục cho sản phẩm.\n- HS chia sẻ ý tưởng."},{"ten":"4. Vận dụng","gv":"- GV yêu cầu HS nêu ý tưởng đã chọn và liên hệ hành động biết ơn thầy cô.\n- GV dặn dò chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nêu ý tưởng, liên hệ thực tế.\n- HS chuẩn bị đồ dùng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ tranh, ảnh về nhà giáo qua các thời kì: lớp học tranh tre ngày trước, lớp học hôm nay, thầy cô ở vùng cao; HS thấy được nghề dạy học trong nhiều hoàn cảnh khác nhau.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chọn một bức và kể lại thầy cô trong tranh đang làm gì, HS trong tranh có gì khác với lớp mình.\n⚠ (Miền 4: An toàn) Ảnh tư liệu do GV chọn từ nguồn đáng tin và có ghi nguồn; HS không tự tìm ảnh trên mạng trong giờ học.","hs":"- HS kể được nội dung tranh, ảnh về nhà giáo và nêu cảm nhận.\n- HS so sánh được lớp học trong tranh với lớp học của mình."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":14,"tiet":14,"bai":"Chủ đề 6: BIẾT ƠN THẦY CÔ (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp, ý nghĩa của hình ảnh thầy cô và ngày Nhà giáo Việt Nam 20-11.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, bưu thiếp, sản phẩm 3D) về chủ đề thầy cô.\n- Biết sắp xếp hình, màu và trang trí để thể hiện tình cảm biết ơn thầy cô.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: hình ảnh, clip về hoạt động của thầy cô, ngày Nhà giáo Việt Nam; tranh, bưu thiếp, sản phẩm mĩ thuật về chủ đề thầy cô để làm mẫu; hình minh hoạ các bước vẽ dáng người đơn giản bằng que và khối; thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là giấy vẽ A4 và bút chì; vật liệu thay thế dễ kiếm: mặt sau tờ lịch cũ, bìa carton mỏng, giấy báo cũ, giấy màu, vải vụn và dây len để đắp thêm tóc, áo cho nhân vật.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS đặt bản phác của Tiết 1 và đồ dùng lên bàn, đi kiểm tra nhanh và ghi nhận HS đã phác xong bố cục.\n- GV chiếu 2 bức tranh về thầy cô và hỏi: Trong tranh, hình ảnh nào được vẽ to và rõ nhất? Vì sao hoạ sĩ lại vẽ như vậy?\n- GV hỏi thêm: Em định vẽ thầy cô đang làm gì trong tranh của mình?\n- GV khen ngợi và giới thiệu nhiệm vụ tiết học: vẽ hình chi tiết cho bức tranh về thầy cô.","hs":"- HS đặt bản phác Tiết 1 và đồ dùng lên bàn, tự kiểm tra xem đã đủ bút chì, tẩy, màu chưa.\n- HS quan sát tranh và trả lời: hình cô giáo được vẽ to ở giữa để làm hình ảnh chính, các bạn nhỏ vẽ nhỏ hơn ở xung quanh.\n- HS nêu ý tưởng: em vẽ cô đang giảng bài, em vẽ cảnh chúng em tặng hoa cô ngày 20-11.\n- HS mở SGK, ghi tên bài và chuẩn bị bản phác để vẽ tiếp."},{"ten":"2. Khám phá","gv":"- (8 phút) GV hướng dẫn HS vẽ hình chi tiết theo 4 bước: Bước 1 xác định lại hình chính là thầy cô, vẽ to và gần giữa tranh; Bước 2 vẽ dáng người bằng nét que trước (đầu là hình tròn, thân là một nét dọc, tay chân là các nét gấp khúc); Bước 3 bọc khối cho nét que thành thân, tay, chân có độ dày; Bước 4 thêm chi tiết tóc, mắt, miệng, trang phục và đồ vật đi kèm như phấn, sách, bó hoa.\n- GV thị phạm chậm bước 2 và bước 3 lên bảng: vẽ dáng cô đang đứng viết bảng, dáng cô đang cúi xuống bên bàn HS, mỗi dáng chỉ mất khoảng 30 giây bằng nét que.\n- GV hỏi: Muốn nhìn ra cô đang viết bảng thì tay cô để ở đâu? GV lưu ý kĩ thuật: vẽ nhẹ tay bằng bút chì để dễ tẩy, đầu người khoảng bằng một phần sáu chiều cao thân, hình phụ vẽ nhỏ hơn và lùi ra sau hình chính.\n- GV nhắc HS chưa tự tin có thể vẽ dáng đơn giản, không cần giống hệt, quan trọng là thể hiện được hoạt động và tình cảm.","hs":"- HS quan sát và nhắc lại 4 bước vẽ hình chi tiết theo đúng thứ tự.\n- HS theo dõi GV thị phạm dáng người bằng nét que, vẽ thử ra giấy nháp hai dáng.\n- HS trả lời: tay cô giơ cao ngang vai, mặt hơi nghiêng về phía bảng thì mới giống đang viết bảng.\n- HS nhắc lại lưu ý kĩ thuật: vẽ nhẹ tay, hình chính to và rõ, hình phụ nhỏ hơn ở phía sau."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV cho HS thực hành hoàn thiện phần hình cho bức tranh hoặc sản phẩm về thầy cô theo đúng 4 bước đã hướng dẫn.\n- GV nêu yêu cầu cụ thể: tranh có ít nhất một hình chính là thầy cô và hai hình phụ (HS, bàn ghế, bảng, cây, bó hoa); các hình không bị dính sát mép giấy.\n- GV đi từng bàn hỗ trợ: cầm tay chỉ lại cách vẽ nét que cho HS còn khó khăn, gợi ý HS vẽ nhanh thì thêm chi tiết nền như cửa sổ, khẩu hiệu, chậu hoa.\n- GV nhắc HS dùng tẩy nhẹ nhàng để không rách giấy, tẩy xong phủi sạch vụn tẩy; báo trước còn 3 phút để hoàn thiện nét và cất bút chì.","hs":"- HS thực hành vẽ hình chi tiết theo 4 bước, bắt đầu từ hình chính rồi mới đến hình phụ.\n- HS kiểm tra bố cục: hình chính to và rõ, hình phụ nhỏ hơn, không có hình bị cắt sát mép giấy.\n- HS chia sẻ tiến độ với bạn cùng bàn, nhờ bạn góp ý một điểm cần sửa.\n- HS dùng tẩy nhẹ tay, phủi sạch vụn tẩy, hoàn thiện nét và cất bút chì đúng chỗ."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày bản vẽ hình trên bảng nhóm theo chủ đề: nhóm tranh Cô dạy học, nhóm tranh Ngày 20-11.\n- GV nêu tiêu chí nhận xét bản vẽ hình: (1) có đủ hình ảnh chính là thầy cô và hình phụ; (2) bố cục cân đối, hình chính nổi rõ; (3) dáng người thể hiện được hoạt động; (4) nét vẽ sạch, không lem, không rách giấy.\n- GV cho HS đi xem một vòng, dán sao vào bài mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV hỏi chốt: Nhìn vào tranh của bạn, em đoán thầy cô đang làm gì? GV chốt: sắp xếp hình chính rõ và dáng người đúng hoạt động thì người xem hiểu ngay câu chuyện trong tranh.\n- GV dặn dò chuẩn bị màu vẽ, khăn lau và hộp đựng nước cho tiết sau để tô màu hoàn thiện tranh.","hs":"- HS dán bản vẽ hình lên bảng nhóm đúng chủ đề, ghi tên vào góc bài.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét bản vẽ hình.\n- HS đi xem, dán sao và nói: Mình thích bài này vì bạn vẽ được dáng cô đang cúi xuống chỉ bài.\n- HS trả lời câu hỏi chốt và tự đánh giá bố cục bài của mình theo tiêu chí.\n- HS ghi nhớ chuẩn bị màu vẽ, khăn lau, hộp nước cho tiết sau."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":15,"tiet":15,"bai":"Chủ đề 6: BIẾT ƠN THẦY CÔ (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp, ý nghĩa của hình ảnh thầy cô và ngày Nhà giáo Việt Nam 20-11.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, bưu thiếp, sản phẩm 3D) về chủ đề thầy cô.\n- Biết sắp xếp hình, màu và trang trí để thể hiện tình cảm biết ơn thầy cô.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: hình ảnh, clip về hoạt động của thầy cô, ngày Nhà giáo Việt Nam; tranh, bưu thiếp, sản phẩm mĩ thuật về chủ đề thầy cô để làm mẫu; hai bản tranh cùng một hình, một bản tô màu có đậm nhạt và một bản tô đều màu để so sánh; bảng pha màu, khăn lau; thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là màu sáp hoặc màu nước; vật liệu thay thế dễ kiếm: bút dạ, phấn màu, giấy màu xé dán thay cho tô màu, giấy báo cũ và vải vụn dán làm nền cho lớp thiếu màu vẽ.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS đặt bản vẽ hình của Tiết 2 và hộp màu lên bàn, kiểm tra nhanh, cho HS thiếu màu mượn từ khay dự trữ của lớp.\n- GV chiếu hai bản tranh cùng một hình, một bản tô đều một sắc độ và một bản có đậm nhạt, rồi hỏi: Bức nào nhìn rõ hình cô giáo hơn? Vì sao?\n- GV hỏi thêm: Muốn màu chỗ này đậm hơn thì em làm cách nào?\n- GV khen ngợi và giới thiệu nhiệm vụ tiết học: chọn màu và tô màu hoàn thiện sản phẩm về thầy cô.","hs":"- HS đặt bản vẽ hình Tiết 2 và hộp màu, khăn lau lên bàn; HS thiếu màu lên mượn.\n- HS quan sát và trả lời: bức thứ hai rõ hơn vì hình cô được tô đậm còn nền tô nhạt nên hình nổi lên.\n- HS trả lời: tô chồng nhiều lớp màu, ấn tay mạnh hơn hoặc pha ít nước hơn thì màu đậm hơn.\n- HS mở SGK, ghi tên bài và chuẩn bị bản vẽ hình để tô màu."},{"ten":"2. Khám phá","gv":"- (8 phút) GV hướng dẫn HS chọn và phối màu cho sản phẩm theo 4 bước: Bước 1 chọn một màu chủ đạo hợp không khí ngày 20-11 (đỏ, hồng, vàng ấm); Bước 2 tô hình chính là thầy cô trước bằng màu tươi và đậm; Bước 3 tô hình phụ và nền bằng màu nhạt hơn để không lấn hình chính; Bước 4 nhấn đậm ở viền hình chính và thêm chi tiết trang trí.\n- GV thị phạm chậm cách tô gọn và đều: tô từ trong ra sát nét viền, nét chì đi cùng một hướng, chỗ giáp mép thì tô chậm và nhẹ tay; muốn có đậm nhạt thì tô chồng thêm 2 đến 3 lớp ở chỗ cần đậm.\n- GV làm mẫu cách pha màu nước: nhúng cọ vào nước rồi gạt bớt, lấy màu vừa phải, pha trên bảng pha chứ không pha ngay trên tranh; rửa cọ và thấm khăn khi đổi màu.\n- GV hỏi: Nếu em lỡ tô lem ra ngoài thì xử lí thế nào? GV chốt cách chữa và nhắc giữ vệ sinh, không vẩy màu, không để nước đổ ra bàn bạn.","hs":"- HS quan sát và nhắc lại 4 bước tô màu, nêu màu chủ đạo mình chọn.\n- HS theo dõi GV thị phạm cách tô gọn, tô đều và cách tạo đậm nhạt bằng cách tô chồng lớp.\n- HS quan sát cách pha màu nước, nhắc lại thao tác gạt cọ và rửa cọ khi đổi màu.\n- HS trả lời: có thể viền lại nét bằng bút màu đậm hoặc biến vệt lem thành một chi tiết như bông hoa, đám mây."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV cho HS thực hành tô màu hoàn thiện sản phẩm theo đúng thứ tự: hình chính trước, hình phụ sau, nền cuối cùng.\n- GV nêu yêu cầu cụ thể: bài có ít nhất ba màu, thấy rõ chỗ đậm chỗ nhạt, hình chính nổi bật hơn nền.\n- GV đi từng bàn hỗ trợ: tô mẫu giúp một mảng nhỏ cho HS còn lúng túng, nhắc HS tô màu nước phải chờ mảng bên cạnh khô mới tô tiếp để không loang.\n- GV nhắc còn 3 phút cuối để hoàn thiện, thấm khô tranh, rửa cọ, đổ nước bẩn đúng nơi quy định và lau bàn.","hs":"- HS thực hành tô màu theo thứ tự hình chính, hình phụ rồi đến nền.\n- HS tạo đậm nhạt bằng cách tô chồng lớp ở chỗ cần nhấn và tô nhẹ ở chỗ cần nhạt.\n- HS chia sẻ tiến độ với bạn cùng bàn và nhờ bạn góp ý về màu sắc.\n- HS hoàn thiện bài, thấm khô tranh, rửa cọ, đổ nước bẩn đúng chỗ và lau sạch bàn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày sản phẩm đã tô màu thành một phòng tranh mini ở góc lớp, xếp theo hai bảng nhóm: bảng Tranh và bảng Bưu thiếp.\n- GV nêu tiêu chí nhận xét: (1) đủ hình ảnh chính về thầy cô; (2) bố cục cân đối, hình chính nổi rõ; (3) màu sắc hài hoà, có đậm nhạt; (4) bài sạch sẽ, tô gọn, có ý tưởng riêng.\n- GV cho HS đi xem, dán sao vào bài mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV hỏi chốt: Em đã dùng những màu nào để thể hiện tình cảm với thầy cô? GV chốt: màu ấm và cách tô có đậm nhạt giúp bức tranh nói được tình cảm biết ơn của em.\n- GV dặn dò: giữ sản phẩm phẳng trong cặp, chuẩn bị cho tiết trưng bày và giới thiệu sản phẩm cuối chủ đề.","hs":"- HS dán sản phẩm lên bảng nhóm đúng loại, ghi tên và tên bài vào góc.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì màu áo cô rất tươi và nổi trên nền nhạt.\n- HS trả lời câu hỏi chốt, tự nhận xét về màu sắc trong bài của mình.\n- HS cất sản phẩm phẳng phiu và ghi nhớ chuẩn bị cho tiết sau."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":16,"tiet":16,"bai":"Chủ đề 6: BIẾT ƠN THẦY CÔ (Tiết 4)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp, ý nghĩa của hình ảnh thầy cô và ngày Nhà giáo Việt Nam 20-11.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, bưu thiếp, sản phẩm 3D) về chủ đề thầy cô.\n- Biết sắp xếp hình, màu và trang trí để thể hiện tình cảm biết ơn thầy cô.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 2.5 CB1a: Phân biệt được chuẩn mực hành vi đơn giản và biết cách sử dụng công nghệ số và tương tác trong môi trường số: HS viết được lời chúc chân thành, lễ phép cho thầy cô.","dodung":"- Giáo viên: hình ảnh, clip về hoạt động của thầy cô, ngày Nhà giáo Việt Nam; tranh, bưu thiếp, sản phẩm mĩ thuật về chủ đề thầy cô để làm mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm của HS ở Tiết 3.\n- GV khen ngợi và giới thiệu nội dung tiết học.","hs":"- HS trưng bày sản phẩm Tiết 3.\n- HS mở bài học."},{"ten":"2. Khám phá","gv":"- GV hướng dẫn HS hoàn thiện, trang trí thêm cho sản phẩm (viền, chữ, chi tiết trang trí).\n- GV gợi ý cách viết lời chúc ngắn gửi thầy cô.","hs":"- HS hoàn thiện và trang trí thêm cho sản phẩm.\n- HS viết lời chúc gửi thầy cô."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS hoàn thành sản phẩm và chuẩn bị giới thiệu.\n- GV quan sát, hỗ trợ HS.","hs":"- HS hoàn thành sản phẩm.\n- HS chuẩn bị giới thiệu."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trưng bày, nhận xét cuối chủ đề: sản phẩm thể hiện tình cảm gì với thầy cô.\n- GV dặn dò ôn tập chuẩn bị kiểm tra, đánh giá học kì 1.","hs":"- HS trưng bày, giới thiệu sản phẩm và tình cảm với thầy cô.\n- HS cùng nhận xét, đánh giá."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp bưu thiếp của HS và ghép thành một trang thiệp chung của lớp gửi tới thầy cô nhân ngày 20 tháng 11, mỗi ô có ảnh thiếp và lời chúc của một bạn.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS đọc lời chúc của mình cho nhóm nghe, sửa lại cho gọn và lễ phép trước khi GV đưa vào trang thiệp chung.\n⚠ (Miền 4: An toàn) Trang thiệp chung chỉ gửi tới thầy cô trong trường; không ghi số điện thoại, địa chỉ nhà của ai lên thiệp; lời chúc phải do chính HS nghĩ ra.","hs":"- HS viết được lời chúc chân thành, lễ phép cho thầy cô.\n- HS góp ý giúp bạn sửa lời chúc cho hay hơn."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":17,"tiet":17,"bai":"ÔN TẬP, ĐÁNH GIÁ CUỐI HỌC KÌ I","yccd":"1. Năng lực mĩ thuật\n- Củng cố, hệ thống kiến thức, kĩ năng mĩ thuật đã học trong học kì 1 (nét, hình, khối, màu sắc, vật liệu).\n- Vận dụng kiến thức đã học để thực hiện một sản phẩm mĩ thuật theo ý thích.\n- Tự đánh giá được sản phẩm của mình và của bạn.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 3.1 CB1a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS nhận ra quá trình học của mình qua hồ sơ ảnh sản phẩm.","dodung":"- Giáo viên: bảng hệ thống các chủ đề học kì 1; một số sản phẩm mĩ thuật tiêu biểu của HS; tiêu chí đánh giá đơn giản; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cùng HS hệ thống lại các chủ đề đã học ở học kì 1 bằng trò chơi/sơ đồ.\n- GV giới thiệu nội dung tiết kiểm tra, đánh giá.","hs":"- HS nhắc lại tên các chủ đề và kiến thức đã học.\n- HS lắng nghe yêu cầu."},{"ten":"2. Khám phá","gv":"- GV nêu yêu cầu: mỗi HS chọn một nội dung yêu thích trong học kì 1 để thể hiện thành sản phẩm mĩ thuật.\n- GV gợi ý về hình thức, chất liệu, màu sắc.","hs":"- HS chọn nội dung và hình thức thể hiện.\n- HS chuẩn bị đồ dùng, vật liệu."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS thực hành hoàn thiện sản phẩm mĩ thuật thể hiện kiến thức, kĩ năng đã học.\n- GV quan sát, hỗ trợ, ghi nhận sự tiến bộ của HS.","hs":"- HS thực hành, hoàn thiện sản phẩm.\n- HS vận dụng nét, hình, khối, màu đã học."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trưng bày, cùng HS đánh giá sản phẩm theo tiêu chí đơn giản (hoàn thành, có sáng tạo, biết phối màu).\n- GV nhận xét, đánh giá kết quả học kì 1, động viên HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS tự đánh giá và đánh giá sản phẩm của bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cùng HS lập hồ sơ mĩ thuật học kì I trên máy: mỗi HS một trang có ảnh các sản phẩm đã làm, xếp theo thứ tự thời gian, dưới mỗi ảnh ghi tên chủ đề.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS xem lại trang của mình, chọn một sản phẩm ưng ý nhất và nói với bạn cùng bàn vì sao mình chọn sản phẩm đó.\n⚠ (Miền 4: An toàn) Hồ sơ của bạn nào thì bạn ấy và GV cùng xem; không mở hồ sơ của bạn khi chưa được phép, không đem bài của bạn ra chê trước lớp.","hs":"- HS nhận ra quá trình học của mình qua hồ sơ ảnh sản phẩm.\n- HS chọn và nói được lí do chọn sản phẩm ưng ý nhất."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":18,"tiet":18,"bai":"Chủ đề 7: CẢNH VẬT QUANH EM (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp của cảnh vật, phong cảnh quanh em (cây cối, nhà cửa, đường làng…).\n- Vẽ/tạo được sản phẩm mĩ thuật thể hiện phong cảnh quen thuộc, biết sắp xếp hình chính – phụ, xa – gần.\n- Sử dụng được màu sắc, chất liệu phù hợp để thể hiện phong cảnh.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.2 CB1a: Phát hiện được độ tin cậy và độ chính xác của các nguồn chung của dữ liệu, thông tin và nội dung số: HS kiểm chứng được quy luật ấy khi nhìn cảnh thật ngoài sân.","dodung":"- Giáo viên: hình ảnh, clip về cảnh vật, phong cảnh quê hương; tranh phong cảnh của hoạ sĩ và sản phẩm mĩ thuật về phong cảnh để làm mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem hình ảnh cảnh vật quen thuộc quanh em và hỏi cảm nhận.\n- GV khen ngợi và giới thiệu chủ đề.","hs":"- HS xem, kể tên cảnh vật quen thuộc.\n- HS mở bài học, ghi tên bài."},{"ten":"2. Khám phá","gv":"- GV cho HS quan sát tranh phong cảnh trong SGK và một số hình ảnh phong cảnh; phân tích hình chính – phụ, xa – gần, màu sắc.\n- GV gợi ý HS chọn một cảnh vật để thể hiện.","hs":"- HS quan sát, nhận ra cách sắp xếp hình và màu trong tranh phong cảnh.\n- HS chọn cảnh vật yêu thích."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV hướng dẫn HS phác ý tưởng và bố cục cho tranh phong cảnh.\n- GV cho HS vẽ phác bố cục xa – gần.","hs":"- HS phác ý tưởng và bố cục tranh phong cảnh.\n- HS chia sẻ ý tưởng."},{"ten":"4. Vận dụng","gv":"- GV yêu cầu HS nêu ý tưởng và liên hệ vẻ đẹp cảnh vật quê hương.\n- GV dặn dò chuẩn bị đồ dùng.","hs":"- HS nêu ý tưởng, liên hệ thực tế.\n- HS chuẩn bị đồ dùng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu một ảnh phong cảnh rồi lần lượt che phần gần, che phần xa để HS nhận ra vật ở gần thì to, rõ, màu đậm còn vật ở xa thì nhỏ, mờ, màu nhạt; che rồi mở lại nhiều lần trên màn hình giúp HS thấy quy luật ấy rõ hơn hẳn so với nhìn một bức tranh in.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS ra cửa sổ nhìn ra sân trường và kiểm chứng lại: cây ở gần và cây ở xa khác nhau thế nào.\n⚠ (Miền 4: An toàn) GV thao tác che, mở trên máy; HS quan sát tại chỗ, khi ra cửa sổ nhìn thì không chen lấn, không trèo lên bậu cửa.","hs":"- HS nêu được quy luật xa gần về độ to, độ rõ và độ đậm của màu.\n- HS kiểm chứng được quy luật ấy khi nhìn cảnh thật ngoài sân."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":19,"tiet":19,"bai":"Chủ đề 7: CẢNH VẬT QUANH EM (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp của cảnh vật, phong cảnh quanh em (cây cối, nhà cửa, đường làng…).\n- Vẽ/tạo được sản phẩm mĩ thuật thể hiện phong cảnh quen thuộc, biết sắp xếp hình chính – phụ, xa – gần.\n- Sử dụng được màu sắc, chất liệu phù hợp để thể hiện phong cảnh.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: hình ảnh, clip về cảnh vật, phong cảnh quê hương; tranh phong cảnh của hoạ sĩ và sản phẩm mĩ thuật về phong cảnh để làm mẫu; một tranh phong cảnh vẽ sai xa gần để HS so sánh; hình minh hoạ các bước vẽ cây, nhà đơn giản; thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là giấy vẽ và bút chì; vật liệu thay thế dễ kiếm: mặt sau tờ lịch cũ, giấy báo cũ, bìa carton mỏng, giấy màu xé dán làm mảng cây và mảng ruộng, lá cây khô dán làm tán cây.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS đặt bản phác của Tiết 1 và đồ dùng lên bàn, kiểm tra nhanh và khen HS đã chọn được cảnh vật để vẽ.\n- GV chiếu ảnh một con đường làng có hàng cây và hỏi: Cây nào ở gần em, cây nào ở xa? Nhờ dấu hiệu nào mà em biết?\n- GV hỏi thêm: Trong bản phác của em, cảnh nào là cảnh chính?\n- GV khen ngợi và giới thiệu nhiệm vụ tiết học: vẽ hình chi tiết cho bức tranh phong cảnh.","hs":"- HS đặt bản phác Tiết 1 và đồ dùng lên bàn, tự kiểm tra bút chì, tẩy, màu.\n- HS quan sát ảnh và trả lời: cây ở gần thì to, rõ chi tiết và ở phía dưới tranh; cây ở xa thì nhỏ, mờ và ở phía trên.\n- HS nêu cảnh chính trong bài của mình: cây đa đầu làng, ngôi nhà của em, con sông trước ngõ.\n- HS mở SGK, ghi tên bài và chuẩn bị bản phác để vẽ tiếp."},{"ten":"2. Khám phá","gv":"- (8 phút) GV hướng dẫn HS vẽ hình chi tiết cho phong cảnh theo 4 bước: Bước 1 kẻ nhẹ một đường ngang làm đường chân trời để phân biệt xa gần; Bước 2 vẽ hình chính (cây, nhà) to và đặt gần phía dưới tranh; Bước 3 vẽ hình phụ nhỏ hơn, đặt cao hơn và lùi ra sau hình chính; Bước 4 thêm chi tiết như cửa sổ, hàng rào, con đường, đám mây, dáng người.\n- GV thị phạm chậm cách vẽ cây và nhà đơn giản: cây gồm một thân hình ống hơi loe ở gốc, các cành toả ra hình chữ Y, tán là những mảng cong nối nhau; nhà gồm một hình chữ nhật và một hình tam giác làm mái.\n- GV lưu ý kĩ thuật xa gần: vật ở gần vẽ to, đậm nét và có nhiều chi tiết; vật ở xa vẽ nhỏ, nét mảnh, ít chi tiết; các vật có thể che khuất nhau một phần cho tranh có chiều sâu.\n- GV hỏi: Nếu vẽ ngôi nhà ở xa mà to bằng cây ở gần thì tranh sẽ ra sao? GV chốt và nhắc HS vẽ nhẹ tay để còn sửa được.","hs":"- HS quan sát và nhắc lại 4 bước vẽ hình chi tiết cho tranh phong cảnh.\n- HS theo dõi GV thị phạm, vẽ thử một cây và một ngôi nhà ra giấy nháp.\n- HS nhắc lại lưu ý xa gần: gần thì to, đậm, nhiều chi tiết; xa thì nhỏ, mảnh, ít chi tiết.\n- HS trả lời: tranh sẽ bị rối, không thấy được cảnh nào xa cảnh nào gần."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV cho HS thực hành hoàn thiện phần hình cho tranh phong cảnh theo đúng 4 bước, làm bài cá nhân trên giấy vẽ hoặc mặt sau tờ lịch cũ.\n- GV nêu yêu cầu cụ thể: tranh có ít nhất một hình chính và ba hình phụ, thấy rõ lớp cảnh gần và lớp cảnh xa, hình không dính sát mép giấy.\n- GV đi từng bàn hỗ trợ: vẽ mẫu lại tán cây cho HS còn lúng túng, gợi ý HS vẽ nhanh thêm chi tiết như đàn chim, cánh đồng, cầu nhỏ; nhắc HS xé dán giấy màu nếu không quen vẽ nét.\n- GV nhắc HS tẩy nhẹ tay để không rách giấy, phủi sạch vụn tẩy; báo trước còn 3 phút để hoàn thiện nét và cất đồ dùng.","hs":"- HS thực hành vẽ hình chi tiết theo 4 bước, kẻ đường chân trời trước rồi mới vẽ hình.\n- HS kiểm tra bố cục: hình chính to và rõ ở lớp cảnh gần, hình phụ nhỏ hơn ở lớp cảnh xa.\n- HS thêm chi tiết cho tranh sinh động và chia sẻ tiến độ với bạn cùng bàn.\n- HS tẩy nhẹ tay, phủi sạch vụn tẩy, hoàn thiện nét và cất bút chì đúng chỗ."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày bản vẽ hình trên bảng nhóm theo chủ đề: bảng Cảnh làng quê và bảng Cảnh phố phường.\n- GV nêu tiêu chí nhận xét bản vẽ hình: (1) có đủ hình chính và hình phụ; (2) bố cục cân đối, thấy rõ xa gần; (3) hình vẽ rõ đặc điểm của cảnh vật; (4) bài sạch sẽ, nét gọn, có ý tưởng riêng.\n- GV cho HS đi xem, dán sao vào bài mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV hỏi chốt: Trong tranh của bạn, cảnh nào ở gần, cảnh nào ở xa? GV chốt: sắp xếp hình theo xa gần làm cho tranh phong cảnh có chiều sâu và giống thật hơn.\n- GV dặn dò chuẩn bị màu vẽ, khăn lau, hộp nước cho tiết sau để tô màu hoàn thiện tranh.","hs":"- HS dán bản vẽ hình lên bảng nhóm đúng chủ đề, ghi tên vào góc bài.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét bản vẽ hình.\n- HS đi xem, dán sao và nói: Mình thích bài này vì bạn vẽ hàng cây xa nhỏ dần trông rất thật.\n- HS trả lời câu hỏi chốt, chỉ ra lớp cảnh gần và lớp cảnh xa trong bài của bạn.\n- HS tự đánh giá bố cục bài mình và ghi nhớ chuẩn bị màu cho tiết sau."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":20,"tiet":20,"bai":"Chủ đề 7: CẢNH VẬT QUANH EM (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp của cảnh vật, phong cảnh quanh em (cây cối, nhà cửa, đường làng…).\n- Vẽ/tạo được sản phẩm mĩ thuật thể hiện phong cảnh quen thuộc, biết sắp xếp hình chính – phụ, xa – gần.\n- Sử dụng được màu sắc, chất liệu phù hợp để thể hiện phong cảnh.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nhận ra làm nhạt phần ở xa thì tranh có chiều sâu hơn.","dodung":"- Giáo viên: hình ảnh, clip về cảnh vật, phong cảnh quê hương; tranh phong cảnh của hoạ sĩ và sản phẩm mĩ thuật về phong cảnh để làm mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra bản vẽ hình và đồ dùng của HS ở Tiết 2.\n- GV khen ngợi và giới thiệu nội dung tiết học.","hs":"- HS trình bày bản vẽ hình và đồ dùng.\n- HS mở bài học."},{"ten":"2. Khám phá","gv":"- GV hướng dẫn HS chọn và phối màu cho tranh phong cảnh; gợi ý màu của trời, cây, đất, nước.\n- GV thị phạm cách tô màu tạo không gian xa – gần.","hs":"- HS quan sát cách phối màu cho phong cảnh.\n- HS chọn màu cho tranh."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS thực hành tô màu, hoàn thiện tranh phong cảnh.\n- GV quan sát, hỗ trợ HS hoàn thành.","hs":"- HS thực hành tô màu, hoàn thiện tranh.\n- HS chia sẻ tiến độ."},{"ten":"4. Vận dụng","gv":"- GV cho HS trưng bày tranh đã tô màu, cùng nhận xét về màu sắc, không gian.\n- GV dặn dò chuẩn bị cho tiết trưng bày.","hs":"- HS trưng bày, nhận xét về màu sắc.\n- HS chuẩn bị cho tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở một bức tranh phong cảnh trong phần mềm xem ảnh và giảm dần độ đậm của phần nền phía xa để cả lớp thấy ngay bức tranh trở nên sâu hơn; trả lại như cũ rồi làm lại để HS so sánh hai trạng thái.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chỉ ra trong tranh của chính mình chỗ nào cần làm nhạt bớt để tạo chiều sâu.\n⚠ (Miền 4: An toàn) GV điều khiển phần mềm; HS chỉnh bài của mình bằng cách pha loãng màu trên giấy, việc chỉnh trên máy chỉ để nhìn thấy trước kết quả.","hs":"- HS nhận ra làm nhạt phần ở xa thì tranh có chiều sâu hơn.\n- HS chỉ ra và sửa được phần cần làm nhạt trong bài của mình."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":21,"tiet":21,"bai":"Chủ đề 7: CẢNH VẬT QUANH EM (Tiết 4)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp của cảnh vật, phong cảnh quanh em (cây cối, nhà cửa, đường làng…).\n- Vẽ/tạo được sản phẩm mĩ thuật thể hiện phong cảnh quen thuộc, biết sắp xếp hình chính – phụ, xa – gần.\n- Sử dụng được màu sắc, chất liệu phù hợp để thể hiện phong cảnh.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS xem phòng tranh và nhận ra tên tác giả của từng bức.","dodung":"- Giáo viên: hình ảnh, clip về cảnh vật, phong cảnh quê hương; tranh phong cảnh của hoạ sĩ và sản phẩm mĩ thuật về phong cảnh để làm mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm của HS ở Tiết 3.\n- GV khen ngợi và giới thiệu nội dung tiết học.","hs":"- HS trưng bày sản phẩm Tiết 3.\n- HS mở bài học."},{"ten":"2. Khám phá","gv":"- GV hướng dẫn HS hoàn thiện, chỉnh sửa và trang trí thêm cho tranh phong cảnh.\n- GV gợi ý cách đặt tên cho tranh.","hs":"- HS hoàn thiện, chỉnh sửa tranh.\n- HS đặt tên cho tranh."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS hoàn thành sản phẩm và chuẩn bị giới thiệu.\n- GV quan sát, hỗ trợ HS.","hs":"- HS hoàn thành sản phẩm.\n- HS chuẩn bị giới thiệu."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trưng bày, nhận xét cuối chủ đề: tranh thể hiện cảnh vật gì, cảm xúc về cảnh vật quê hương.\n- GV dặn dò chuẩn bị chủ đề Chân dung người thân trong gia đình.","hs":"- HS trưng bày, giới thiệu tranh và cảm xúc.\n- HS cùng nhận xét, đánh giá."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp tranh phong cảnh của cả lớp và ghép thành một phòng tranh theo chủ đề quê hương, dưới mỗi tranh ghi tên tác giả và địa danh bạn đã vẽ.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS đi xem phòng tranh trên màn hình, chọn một bức và nói bức đó gợi cho mình nhớ đến nơi nào.\n⚠ (Miền 4: An toàn) Tranh của ai thì ghi tên người ấy; muốn đưa phòng tranh của lớp cho lớp khác xem thì phải hỏi ý kiến các bạn có tranh trong đó.","hs":"- HS xem phòng tranh và nhận ra tên tác giả của từng bức.\n- HS nêu được cảm nhận về tranh phong cảnh của bạn."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":22,"tiet":22,"bai":"Chủ đề 8: CHÂN DUNG NGƯỜI THÂN TRONG GIA ĐÌNH (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được đặc điểm khuôn mặt, mái tóc và biểu cảm của người thân.\n- Vẽ/tạo được sản phẩm mĩ thuật thể hiện chân dung người thân trong gia đình.\n- Biết sử dụng nét, hình, màu để thể hiện đặc điểm và tình cảm với người thân.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đọc được cảm xúc trên gương mặt qua chi tiết mắt, miệng phóng to.","dodung":"- Giáo viên: hình ảnh, tranh chân dung của hoạ sĩ và của HS; hình minh hoạ các bước vẽ chân dung; ảnh người thân (nếu có); thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS nghe/hát một bài hát về gia đình và hỏi về những người thân của em.\n- GV khen ngợi và giới thiệu chủ đề.","hs":"- HS nghe/hát, kể về người thân trong gia đình.\n- HS mở bài học, ghi tên bài."},{"ten":"2. Khám phá","gv":"- GV cho HS quan sát tranh chân dung trong SGK; phân tích đặc điểm khuôn mặt, mái tóc, biểu cảm.\n- GV gợi ý HS chọn một người thân để thể hiện.","hs":"- HS quan sát, nhận ra đặc điểm khuôn mặt, biểu cảm trong tranh chân dung.\n- HS chọn người thân để vẽ."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV hướng dẫn HS phác hình khuôn mặt và bố cục chân dung.\n- GV thị phạm cách vẽ khuôn mặt cơ bản.","hs":"- HS phác hình khuôn mặt và bố cục.\n- HS chia sẻ ý tưởng."},{"ten":"4. Vận dụng","gv":"- GV yêu cầu HS nêu ý tưởng và liên hệ tình cảm với người thân.\n- GV dặn dò chuẩn bị đồ dùng.","hs":"- HS nêu ý tưởng, liên hệ thực tế.\n- HS chuẩn bị đồ dùng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu tranh chân dung của hoạ sĩ và ảnh chụp chân dung, phóng to phần mắt và miệng để HS thấy chỉ cần đổi nét miệng, đổi hướng nhìn của mắt là gương mặt đã đổi cảm xúc.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS đoán cảm xúc của người trong từng bức và chỉ ra chi tiết nào cho mình biết điều đó.\n⚠ (Miền 4: An toàn) GV dùng tranh của hoạ sĩ có ghi tên tác giả và ảnh tư liệu đã chuẩn bị; không chiếu ảnh người thân của HS lên màn hình khi gia đình chưa cho phép.","hs":"- HS đọc được cảm xúc trên gương mặt qua chi tiết mắt, miệng phóng to.\n- HS nêu được chi tiết mình sẽ dùng để tả người thân trong tranh."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":23,"tiet":23,"bai":"Chủ đề 8: CHÂN DUNG NGƯỜI THÂN TRONG GIA ĐÌNH (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được đặc điểm khuôn mặt, mái tóc và biểu cảm của người thân.\n- Vẽ/tạo được sản phẩm mĩ thuật thể hiện chân dung người thân trong gia đình.\n- Biết sử dụng nét, hình, màu để thể hiện đặc điểm và tình cảm với người thân.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: hình ảnh, tranh chân dung của hoạ sĩ và của HS; hình minh hoạ các bước vẽ chân dung; bảng vẽ sẵn khuôn mặt trứng có kẻ trục để hướng dẫn vị trí mắt, mũi, miệng; ảnh người thân (nếu có); thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là giấy vẽ và bút chì; vật liệu thay thế dễ kiếm: mặt sau tờ lịch cũ, bìa carton mỏng, giấy báo cũ, dây len làm tóc, vải vụn làm áo, hột hạt làm mắt và cúc áo cho chân dung đắp nổi.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS đặt bản phác chân dung của Tiết 1 và đồ dùng lên bàn, kiểm tra nhanh, khen HS đã phác đúng dáng khuôn mặt.\n- GV tổ chức trò chơi Đoán người thân: mời 2 HS tả đặc điểm người thân của mình (tóc, mắt, kính, nụ cười) để cả lớp đoán đó là ông, bà, bố hay mẹ.\n- GV hỏi: Nhờ đặc điểm nào mà em nhận ra ngay người thân của mình?\n- GV khen ngợi và giới thiệu nhiệm vụ tiết học: vẽ chi tiết khuôn mặt để chân dung giống và có biểu cảm.","hs":"- HS đặt bản phác Tiết 1 và đồ dùng lên bàn, tự kiểm tra bút chì, tẩy, màu.\n- 2 HS tả đặc điểm người thân, cả lớp đoán và giải thích lí do đoán.\n- HS trả lời: nhận ra nhờ mái tóc bạc của bà, cặp kính của bố, nốt ruồi hay nụ cười của mẹ.\n- HS mở SGK, ghi tên bài và chuẩn bị bản phác để vẽ tiếp."},{"ten":"2. Khám phá","gv":"- (8 phút) GV hướng dẫn HS vẽ chi tiết khuôn mặt theo 5 bước: Bước 1 kẻ nhẹ một trục dọc chia đôi khuôn mặt và một trục ngang ở khoảng giữa; Bước 2 vẽ hai mắt nằm trên trục ngang, cách nhau khoảng bằng một con mắt; Bước 3 vẽ mũi ở khoảng giữa từ trục ngang xuống cằm; Bước 4 vẽ miệng ở khoảng giữa mũi và cằm; Bước 5 vẽ tóc, tai, cổ, vai và các đặc điểm riêng.\n- GV thị phạm chậm bước khó là bước 5: vẽ mái tóc ôm theo hình khuôn mặt chứ không dính sát vào trán, tai nằm ngang từ đuôi mắt đến chân mũi.\n- GV gợi ý thể hiện biểu cảm bằng câu hỏi: Muốn vẽ người thân đang vui thì miệng và mắt vẽ thế nào? Muốn vẽ vẻ hiền hậu thì thêm gì?\n- GV nhắc HS thêm đặc điểm riêng để chân dung có hồn: kính của ông, khăn của bà, râu của bố, hoa tai của mẹ; vẽ nhẹ tay bằng bút chì để dễ sửa.","hs":"- HS quan sát và nhắc lại 5 bước vẽ chi tiết khuôn mặt theo đúng thứ tự.\n- HS theo dõi GV thị phạm cách vẽ tóc và tai, vẽ thử ra giấy nháp một khuôn mặt.\n- HS trả lời: vẽ miệng cong lên, mắt hơi cong như hình trăng khuyết thì thấy đang vui; thêm nếp nhăn nhẹ ở đuôi mắt cho vẻ hiền hậu.\n- HS nêu đặc điểm riêng mình sẽ vẽ cho người thân và ghi nhớ vẽ nhẹ tay để dễ tẩy sửa."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV cho HS thực hành hoàn thiện phần hình cho chân dung theo đúng 5 bước, làm bài cá nhân trên giấy vẽ hoặc mặt sau tờ lịch cũ.\n- GV nêu yêu cầu cụ thể: chân dung có đủ mắt, mũi, miệng, tóc, tai, cổ vai; có ít nhất một đặc điểm riêng của người thân; khuôn mặt đặt gần giữa và chiếm phần lớn tờ giấy.\n- GV đi từng bàn hỗ trợ: chỉ lại vị trí trục cho HS vẽ mắt quá cao, gợi ý HS làm chân dung đắp nổi bằng dây len làm tóc, vải vụn làm áo nếu thích cách khác.\n- GV nhắc HS tẩy nhẹ tay, phủi sạch vụn tẩy; báo trước còn 3 phút để hoàn thiện nét và cất đồ dùng gọn gàng.","hs":"- HS thực hành vẽ chi tiết chân dung theo 5 bước, kẻ trục trước rồi mới vẽ mắt, mũi, miệng.\n- HS thể hiện đặc điểm riêng và biểu cảm của người thân trên khuôn mặt.\n- HS kiểm tra lại tỉ lệ và vị trí các bộ phận, chia sẻ tiến độ với bạn cùng bàn.\n- HS tẩy nhẹ tay, phủi sạch vụn tẩy, hoàn thiện nét và cất bút chì đúng chỗ."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày bản vẽ hình trên bảng nhóm thành một phòng tranh chân dung theo chủ đề: bảng Ông bà, bảng Bố mẹ, bảng Anh chị em.\n- GV nêu tiêu chí nhận xét bản vẽ hình: (1) đủ các bộ phận của khuôn mặt, đặt đúng vị trí; (2) khuôn mặt cân đối, chiếm phần lớn tờ giấy; (3) thể hiện được đặc điểm riêng và biểu cảm; (4) bài sạch sẽ, nét gọn, có ý tưởng riêng.\n- GV cho HS đi xem, dán sao vào bài mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV hỏi chốt: Nhìn tranh của bạn, em đoán đó là ai và người ấy đang vui hay đang trầm ngâm? GV chốt: chỉ cần vẽ đúng vị trí các bộ phận và thêm một đặc điểm riêng là chân dung đã nhận ra được người thân.\n- GV dặn dò chuẩn bị màu vẽ, khăn lau, hộp nước cho tiết sau để tô màu hoàn thiện chân dung.","hs":"- HS dán bản vẽ hình lên bảng nhóm đúng chủ đề, ghi tên người thân vào góc bài.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét bản vẽ hình.\n- HS đi xem, dán sao và nói: Mình thích bài này vì bạn vẽ được cặp kính và nụ cười của ông.\n- HS trả lời câu hỏi chốt, nhận xét về đặc điểm và biểu cảm trong bài của bạn.\n- HS tự đánh giá bài mình theo tiêu chí và ghi nhớ chuẩn bị màu cho tiết sau."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":24,"tiet":24,"bai":"Chủ đề 8: CHÂN DUNG NGƯỜI THÂN TRONG GIA ĐÌNH (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được đặc điểm khuôn mặt, mái tóc và biểu cảm của người thân.\n- Vẽ/tạo được sản phẩm mĩ thuật thể hiện chân dung người thân trong gia đình.\n- Biết sử dụng nét, hình, màu để thể hiện đặc điểm và tình cảm với người thân.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: hình ảnh, tranh chân dung của hoạ sĩ và của HS; hình minh hoạ các bước vẽ chân dung; bảng pha màu da mẫu (vàng nhạt pha chút hồng và chút nâu); hai bản chân dung, một bản tô nền nhạt và một bản tô nền đậm để so sánh; ảnh người thân (nếu có); thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là màu sáp hoặc màu nước; vật liệu thay thế dễ kiếm: bút dạ, phấn màu, giấy màu xé dán làm tóc và áo, giấy báo cũ, vải vụn, dây len cho lớp thiếu màu vẽ.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS đặt bản vẽ hình của Tiết 2 và hộp màu lên bàn, kiểm tra nhanh và cho HS thiếu màu mượn từ khay dự trữ của lớp.\n- GV chiếu hai bản chân dung cùng một hình, một bản nền nhạt và một bản nền đậm, rồi hỏi: Bản nào khuôn mặt nổi rõ hơn? Vì sao?\n- GV hỏi thêm: Màu da người thường được pha từ những màu nào?\n- GV khen ngợi và giới thiệu nhiệm vụ tiết học: chọn màu và tô hoàn thiện chân dung người thân.","hs":"- HS đặt bản vẽ hình Tiết 2, hộp màu và khăn lau lên bàn; HS thiếu màu lên mượn.\n- HS quan sát và trả lời: bản nền nhạt làm khuôn mặt nổi hơn vì nền không lấn át hình chính.\n- HS trả lời: màu da pha từ màu vàng nhạt với một chút hồng và một chút nâu.\n- HS mở SGK, ghi tên bài và chuẩn bị bản vẽ hình để tô màu."},{"ten":"2. Khám phá","gv":"- (8 phút) GV hướng dẫn HS chọn và phối màu cho chân dung theo 4 bước: Bước 1 tô màu da cho mặt, cổ, tai bằng một lớp màu nhạt và đều; Bước 2 tô màu tóc đậm hơn màu da để khuôn mặt sáng lên; Bước 3 tô trang phục bằng màu mà người thân hay mặc; Bước 4 tô nền bằng màu nhạt hoặc màu tương phản nhẹ, rồi nhấn đậm ở viền khuôn mặt và tròng mắt.\n- GV thị phạm chậm cách pha màu da trên bảng pha: lấy màu vàng làm chính, thêm một chút hồng, thử lên mảnh giấy nháp trước khi tô lên bài.\n- GV lưu ý kĩ thuật tạo đậm nhạt trên khuôn mặt: tô đậm hơn ở hai bên má sát tóc và dưới cằm, để nhạt ở trán, sống mũi, gò má; chừa một chấm trắng nhỏ trong tròng mắt cho mắt long lanh.\n- GV hỏi: Nếu tóc và nền cùng một màu đậm thì chuyện gì xảy ra? GV chốt cách tránh và nhắc giữ vệ sinh, rửa cọ khi đổi màu, không vẩy màu ra bài bạn.","hs":"- HS quan sát và nhắc lại 4 bước tô màu chân dung theo đúng thứ tự.\n- HS theo dõi GV pha màu da, tự pha thử trên bảng pha và thử lên giấy nháp.\n- HS nhắc lại cách tạo đậm nhạt trên khuôn mặt và mẹo chừa chấm sáng ở tròng mắt.\n- HS trả lời: tóc sẽ lẫn vào nền, không nhìn rõ khuôn mặt nên phải đổi màu nền nhạt hơn."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV cho HS thực hành tô màu hoàn thiện chân dung theo thứ tự: da, tóc, trang phục, nền.\n- GV nêu yêu cầu cụ thể: bài có ít nhất ba màu, khuôn mặt sáng và nổi hơn nền, thấy rõ chỗ đậm chỗ nhạt.\n- GV đi từng bàn hỗ trợ: tô mẫu giúp một mảng nhỏ cho HS còn lúng túng, nhắc HS dùng màu nước phải chờ mảng cạnh khô mới tô tiếp để không loang sang mặt.\n- GV nhắc còn 3 phút cuối để hoàn thiện, thấm khô bài, rửa cọ, đổ nước bẩn đúng nơi quy định và lau bàn.","hs":"- HS thực hành tô màu theo thứ tự da, tóc, trang phục rồi đến nền.\n- HS tạo đậm nhạt cho khuôn mặt, chừa chấm sáng ở tròng mắt, viền lại nét cho rõ.\n- HS chia sẻ tiến độ với bạn cùng bàn và nhờ bạn góp ý về màu sắc.\n- HS hoàn thiện bài, thấm khô, rửa cọ, đổ nước bẩn đúng chỗ và lau sạch bàn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày sản phẩm đã tô màu thành phòng tranh chân dung gia đình ở góc lớp, xếp theo bảng nhóm Ông bà, Bố mẹ, Anh chị em.\n- GV nêu tiêu chí nhận xét: (1) đủ các bộ phận, thể hiện được đặc điểm riêng; (2) bố cục cân đối, khuôn mặt nổi rõ trên nền; (3) màu sắc hài hoà, có đậm nhạt; (4) bài sạch sẽ, tô gọn, có ý tưởng riêng.\n- GV cho HS đi xem, dán sao vào bài mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV hỏi chốt: Em đã dùng màu nào cho tóc và nền để khuôn mặt nổi lên? GV chốt: chọn màu có đậm nhạt hợp lí giúp chân dung vừa giống người thân vừa thể hiện được tình cảm của em.\n- GV dặn dò: giữ bài phẳng trong cặp, chuẩn bị cho tiết trưng bày và giới thiệu sản phẩm cuối chủ đề.","hs":"- HS dán sản phẩm lên bảng nhóm đúng chủ đề, ghi tên mình và tên người thân vào góc bài.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì màu tóc bạc của bà trông rất giống thật.\n- HS trả lời câu hỏi chốt và tự nhận xét về màu sắc trong bài của mình.\n- HS cất bài phẳng phiu và ghi nhớ chuẩn bị cho tiết sau."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":25,"tiet":25,"bai":"Chủ đề 8: CHÂN DUNG NGƯỜI THÂN TRONG GIA ĐÌNH (Tiết 4)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được đặc điểm khuôn mặt, mái tóc và biểu cảm của người thân.\n- Vẽ/tạo được sản phẩm mĩ thuật thể hiện chân dung người thân trong gia đình.\n- Biết sử dụng nét, hình, màu để thể hiện đặc điểm và tình cảm với người thân.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 3.1 CB1a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS viết được một câu giới thiệu về người mình vẽ.","dodung":"- Giáo viên: hình ảnh, tranh chân dung của hoạ sĩ và của HS; hình minh hoạ các bước vẽ chân dung; ảnh người thân (nếu có); thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm của HS ở Tiết 3.\n- GV khen ngợi và giới thiệu nội dung tiết học.","hs":"- HS trưng bày sản phẩm Tiết 3.\n- HS mở bài học."},{"ten":"2. Khám phá","gv":"- GV hướng dẫn HS hoàn thiện, trang trí thêm cho chân dung (nền, khung, chi tiết).\n- GV gợi ý cách đặt tên và viết lời yêu thương.","hs":"- HS hoàn thiện và trang trí thêm cho chân dung.\n- HS viết lời yêu thương gửi người thân."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS hoàn thành sản phẩm và chuẩn bị giới thiệu.\n- GV quan sát, hỗ trợ HS.","hs":"- HS hoàn thành sản phẩm.\n- HS chuẩn bị giới thiệu."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trưng bày, nhận xét cuối chủ đề: chân dung thể hiện ai, tình cảm gì.\n- GV dặn dò chuẩn bị chủ đề Sinh hoạt trong gia đình.","hs":"- HS trưng bày, giới thiệu chân dung và tình cảm với người thân.\n- HS cùng nhận xét, đánh giá."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp tranh chân dung của HS và ghép thành trang trưng bày có ảnh tranh, tên tác giả và một câu HS viết về người mình vẽ.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS đọc câu giới thiệu của bạn rồi nói một lời khen cụ thể về bức tranh ấy.\n⚠ (Miền 4: An toàn) Trang trưng bày chỉ nêu quan hệ như bà của em, bố của em, không ghi họ tên đầy đủ, nghề nghiệp, nơi làm việc của người thân; không đăng ra ngoài lớp.","hs":"- HS viết được một câu giới thiệu về người mình vẽ.\n- HS nói được lời khen cụ thể cho tranh của bạn."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":26,"tiet":26,"bai":"Chủ đề 9: SINH HOẠT TRONG GIA ĐÌNH (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp của các hoạt động sinh hoạt thường ngày trong gia đình.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, sản phẩm 3D) thể hiện hoạt động sinh hoạt gia đình.\n- Biết thể hiện dáng người, hình ảnh chính – phụ và không khí ấm cúng của gia đình.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS mô tả được dáng người trong từng hoạt động qua clip dừng hình.","dodung":"- Giáo viên: hình ảnh, clip về hoạt động sinh hoạt gia đình; tranh sinh hoạt của hoạ sĩ và của HS; hình minh hoạ các bước vẽ dáng người; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem hình ảnh về các hoạt động trong gia đình (ăn cơm, dọn dẹp, chăm sóc nhau…) và hỏi cảm nhận.\n- GV khen ngợi và giới thiệu chủ đề.","hs":"- HS xem, kể về các hoạt động của gia đình mình.\n- HS mở bài học, ghi tên bài."},{"ten":"2. Khám phá","gv":"- GV cho HS quan sát tranh sinh hoạt gia đình trong SGK; phân tích hình ảnh, dáng người, không gian.\n- GV gợi ý HS chọn một hoạt động để thể hiện.","hs":"- HS quan sát, nhận ra cách thể hiện hoạt động và dáng người.\n- HS chọn hoạt động gia đình để vẽ."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV hướng dẫn HS phác ý tưởng và bố cục cho tranh sinh hoạt.\n- GV thị phạm cách vẽ dáng người đơn giản đang hoạt động.","hs":"- HS phác ý tưởng và bố cục.\n- HS chia sẻ ý tưởng."},{"ten":"4. Vận dụng","gv":"- GV yêu cầu HS nêu ý tưởng và liên hệ không khí gia đình.\n- GV dặn dò chuẩn bị đồ dùng.","hs":"- HS nêu ý tưởng, liên hệ thực tế.\n- HS chuẩn bị đồ dùng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu clip quay chậm và ảnh chụp liên tiếp một người đang quét nhà, nấu cơm, bế em; dừng hình ở từng khoảnh khắc để HS thấy rõ dáng người khi cúi, khi với tay, khi ngồi, những dáng động mà nhìn trực tiếp thì trôi qua quá nhanh.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chọn một dáng đã dừng hình, đứng lên bắt chước rồi kể tay chân mình đang ở tư thế nào.\n⚠ (Miền 4: An toàn) GV dùng clip tư liệu đã chuẩn bị; HS làm mẫu tư thế tại chỗ và giữ khoảng cách với bàn ghế; không quay phim, chụp ảnh bạn trong giờ học.","hs":"- HS mô tả được dáng người trong từng hoạt động qua clip dừng hình.\n- HS làm lại được tư thế đó để lấy dáng cho bài vẽ."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":27,"tiet":27,"bai":"Chủ đề 9: SINH HOẠT TRONG GIA ĐÌNH (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp của các hoạt động sinh hoạt thường ngày trong gia đình.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, sản phẩm 3D) thể hiện hoạt động sinh hoạt gia đình.\n- Biết thể hiện dáng người, hình ảnh chính – phụ và không khí ấm cúng của gia đình.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: hình ảnh, clip về hoạt động sinh hoạt gia đình; tranh sinh hoạt của hoạ sĩ và của HS; hình minh hoạ các bước vẽ dáng người bằng nét que; một bức tranh vẽ dáng người cứng đơ để HS so sánh với tranh có dáng sinh động; thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là giấy vẽ và bút chì; vật liệu thay thế dễ kiếm: mặt sau tờ lịch cũ, giấy báo cũ, bìa carton mỏng, giấy màu xé dán làm dáng người, vải vụn làm quần áo, dây len làm tóc.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS đặt bản phác của Tiết 1 và đồ dùng lên bàn, kiểm tra nhanh và khen HS đã chọn được hoạt động để vẽ.\n- GV tổ chức trò chơi Đoán hoạt động: mời 3 HS lần lượt làm động tác không lời (quét nhà, nấu cơm, xem tivi cùng bố mẹ) cho cả lớp đoán.\n- GV hỏi: Nhờ bộ phận nào trên cơ thể mà em đoán ra bạn đang làm gì?\n- GV khen ngợi và giới thiệu nhiệm vụ tiết học: vẽ chi tiết các nhân vật và cảnh vật cho tranh sinh hoạt gia đình.","hs":"- HS đặt bản phác Tiết 1 và đồ dùng lên bàn, tự kiểm tra bút chì, tẩy, màu.\n- 3 HS lên làm động tác không lời, cả lớp quan sát và đoán tên hoạt động.\n- HS trả lời: nhờ tư thế của tay và chân, nhờ lưng cúi hay người nghiêng mà đoán được.\n- HS nêu hoạt động mình sẽ vẽ và mở SGK, ghi tên bài."},{"ten":"2. Khám phá","gv":"- (8 phút) GV hướng dẫn HS vẽ chi tiết nhân vật và cảnh vật theo 4 bước: Bước 1 xác định nhân vật chính đang làm gì, vẽ to và đặt gần giữa tranh; Bước 2 vẽ dáng người bằng nét que theo đúng tư thế của hoạt động; Bước 3 bọc khối cho nét que thành thân, tay, chân rồi thêm quần áo, tóc, khuôn mặt; Bước 4 vẽ cảnh vật xung quanh như bàn ghế, mâm cơm, tivi, cửa sổ, chậu cây làm hình phụ.\n- GV thị phạm chậm bước 2: vẽ ba dáng người bằng nét que là dáng đứng nấu cơm, dáng ngồi ăn cơm, dáng cúi quét nhà, mỗi dáng chỉ mất khoảng 30 giây.\n- GV lưu ý kĩ thuật: muốn dáng sinh động thì đừng vẽ thân thẳng đơ mà cho lưng hơi cong, tay chân gấp khúc; các nhân vật nên hướng mặt về nhau để tranh có không khí quây quần.\n- GV hỏi: Vẽ thêm gì để người xem biết đây là bữa cơm gia đình? GV chốt và nhắc HS vẽ nhẹ tay để dễ sửa.","hs":"- HS quan sát và nhắc lại 4 bước vẽ chi tiết cho tranh sinh hoạt.\n- HS theo dõi GV thị phạm dáng người bằng nét que, vẽ thử hai dáng ra giấy nháp.\n- HS nhắc lại lưu ý: lưng hơi cong, tay chân gấp khúc, các nhân vật hướng mặt về nhau.\n- HS trả lời: vẽ thêm mâm cơm, bát đũa, nồi cơm, chiếc bàn và bóng đèn trên cao."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV cho HS thực hành hoàn thiện phần hình cho tranh sinh hoạt theo đúng 4 bước, làm bài cá nhân trên giấy vẽ hoặc mặt sau tờ lịch cũ.\n- GV nêu yêu cầu cụ thể: tranh có ít nhất hai nhân vật đang hoạt động và ba hình phụ về đồ vật trong nhà; nhóm nhân vật chính đặt gần giữa và không dính sát mép giấy.\n- GV đi từng bàn hỗ trợ: vẽ lại nét que giúp HS còn lúng túng về tư thế, gợi ý HS vẽ nhanh thêm chi tiết như con mèo, lọ hoa, bức ảnh treo tường; nhắc HS có thể xé dán giấy màu làm dáng người.\n- GV nhắc HS tẩy nhẹ tay, phủi sạch vụn tẩy; báo trước còn 3 phút để hoàn thiện nét và cất đồ dùng gọn gàng.","hs":"- HS thực hành vẽ chi tiết theo 4 bước, vẽ nhân vật chính trước rồi mới đến cảnh vật.\n- HS chỉnh tư thế các nhân vật cho sinh động và hướng về nhau tạo không khí ấm cúng.\n- HS kiểm tra bố cục, chia sẻ tiến độ và nhờ bạn cùng bàn góp ý một điểm cần sửa.\n- HS tẩy nhẹ tay, phủi sạch vụn tẩy, hoàn thiện nét và cất bút chì đúng chỗ."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày bản vẽ hình trên bảng nhóm theo chủ đề: bảng Bữa cơm gia đình, bảng Cùng nhau làm việc nhà, bảng Vui chơi cùng người thân.\n- GV nêu tiêu chí nhận xét bản vẽ hình: (1) có đủ nhân vật chính và hình phụ; (2) bố cục cân đối, nhóm nhân vật chính nổi rõ; (3) dáng người thể hiện đúng hoạt động, sinh động; (4) bài sạch sẽ, nét gọn, có ý tưởng riêng.\n- GV cho HS đi xem, dán sao vào bài mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV hỏi chốt: Nhìn tranh của bạn, em đoán gia đình bạn đang làm gì và cảm nhận không khí ra sao? GV chốt: dáng người đúng hoạt động và cách sắp xếp quây quần làm cho tranh nói được sự ấm áp của gia đình.\n- GV dặn dò chuẩn bị màu vẽ, khăn lau, hộp nước cho tiết sau để tô màu hoàn thiện tranh.","hs":"- HS dán bản vẽ hình lên bảng nhóm đúng chủ đề, ghi tên vào góc bài.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét bản vẽ hình.\n- HS đi xem, dán sao và nói: Mình thích bài này vì bạn vẽ được dáng mẹ đang cúi lau nhà rất giống.\n- HS trả lời câu hỏi chốt, nhận xét bố cục và dáng người trong bài của bạn.\n- HS tự đánh giá bài mình theo tiêu chí và ghi nhớ chuẩn bị màu cho tiết sau."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":28,"tiet":28,"bai":"Chủ đề 9: SINH HOẠT TRONG GIA ĐÌNH (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp của các hoạt động sinh hoạt thường ngày trong gia đình.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, sản phẩm 3D) thể hiện hoạt động sinh hoạt gia đình.\n- Biết thể hiện dáng người, hình ảnh chính – phụ và không khí ấm cúng của gia đình.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: hình ảnh, clip về hoạt động sinh hoạt gia đình; tranh sinh hoạt của hoạ sĩ và của HS; bảng màu chia hai nhóm màu nóng và màu lạnh; hai bản tranh cùng một hình, một bản dùng màu nóng và một bản dùng màu lạnh để so sánh cảm giác; thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là màu sáp hoặc màu nước; vật liệu thay thế dễ kiếm: bút dạ, phấn màu, giấy màu xé dán, giấy báo cũ, vải vụn, dây len dán làm mảng màu cho lớp thiếu màu vẽ.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS đặt bản vẽ hình của Tiết 2 và hộp màu lên bàn, kiểm tra nhanh và cho HS thiếu màu mượn từ khay dự trữ của lớp.\n- GV chiếu hai bản tranh cùng một hình, một bản dùng màu nóng và một bản dùng màu lạnh, rồi hỏi: Bức nào cho em cảm giác ấm cúng hơn? Vì sao?\n- GV hỏi thêm: Kể tên những màu nóng mà em biết.\n- GV khen ngợi và giới thiệu nhiệm vụ tiết học: chọn màu và tô hoàn thiện bức tranh sinh hoạt gia đình.","hs":"- HS đặt bản vẽ hình Tiết 2, hộp màu và khăn lau lên bàn; HS thiếu màu lên mượn.\n- HS quan sát và trả lời: bức dùng màu nóng ấm cúng hơn vì gợi cảm giác như ánh đèn buổi tối.\n- HS kể tên màu nóng: đỏ, cam, vàng, nâu đỏ, hồng.\n- HS mở SGK, ghi tên bài và chuẩn bị bản vẽ hình để tô màu."},{"ten":"2. Khám phá","gv":"- (8 phút) GV hướng dẫn HS chọn và phối màu cho tranh sinh hoạt theo 4 bước: Bước 1 chọn nhóm màu nóng làm màu chủ đạo để tạo không khí gia đình ấm áp; Bước 2 tô nhân vật chính bằng màu tươi và đậm hơn; Bước 3 tô hình phụ và đồ vật bằng màu nhạt hơn; Bước 4 tô nền sau cùng, dùng màu nhạt để nhân vật nổi lên, rồi nhấn đậm ở viền nhân vật chính.\n- GV thị phạm chậm cách tô làm nổi hình chính: tô đậm dần về phía viền nhân vật, để một khoảng sáng phía sau lưng nhân vật như ánh đèn hắt ra.\n- GV lưu ý kĩ thuật: tô cùng một hướng nét cho mảng phẳng đều, không tô đè hai màu nóng lạnh lên nhau khi chưa khô; muốn có đậm nhạt thì tô chồng 2 đến 3 lớp.\n- GV hỏi: Nếu áo của mẹ và màu tường cùng một màu thì tranh sẽ ra sao? GV chốt cách tránh và nhắc giữ vệ sinh, rửa cọ khi đổi màu, không để nước đổ ra bài bạn.","hs":"- HS quan sát và nhắc lại 4 bước tô màu cho tranh sinh hoạt.\n- HS nêu nhóm màu chủ đạo mình chọn và lí do chọn nhóm màu đó.\n- HS theo dõi GV thị phạm cách làm nổi hình chính và cách tạo đậm nhạt bằng tô chồng lớp.\n- HS trả lời: nhân vật sẽ lẫn vào nền nên phải đổi màu áo hoặc tô nền nhạt đi."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV cho HS thực hành tô màu hoàn thiện tranh sinh hoạt theo thứ tự: nhân vật chính, hình phụ rồi đến nền.\n- GV nêu yêu cầu cụ thể: bài có ít nhất ba màu, thấy rõ nhóm màu chủ đạo, nhân vật chính nổi bật hơn nền, có chỗ đậm chỗ nhạt.\n- GV đi từng bàn hỗ trợ: tô mẫu giúp một mảng nhỏ cho HS còn lúng túng, nhắc HS dùng màu nước phải chờ mảng cạnh khô mới tô tiếp để tránh loang màu.\n- GV nhắc còn 3 phút cuối để hoàn thiện, thấm khô tranh, rửa cọ, đổ nước bẩn đúng nơi quy định và lau bàn.","hs":"- HS thực hành tô màu theo thứ tự nhân vật chính, hình phụ rồi đến nền.\n- HS giữ đúng nhóm màu chủ đạo đã chọn và tạo đậm nhạt cho tranh có chiều sâu.\n- HS chia sẻ tiến độ với bạn cùng bàn và nhờ bạn góp ý về màu sắc.\n- HS hoàn thiện bài, thấm khô tranh, rửa cọ, đổ nước bẩn đúng chỗ và lau sạch bàn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày tranh đã tô màu thành phòng tranh mini ở góc lớp, xếp theo bảng nhóm Bữa cơm gia đình, Làm việc nhà, Vui chơi cùng người thân.\n- GV nêu tiêu chí nhận xét: (1) đủ nhân vật chính và hình phụ về sinh hoạt gia đình; (2) bố cục cân đối, nhân vật chính nổi rõ; (3) màu sắc hài hoà, có đậm nhạt, gợi được không khí ấm cúng; (4) bài sạch sẽ, tô gọn, có ý tưởng riêng.\n- GV cho HS đi xem, dán sao vào bài mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV hỏi chốt: Em đã dùng nhóm màu nào và bức tranh cho em cảm giác gì? GV chốt: chọn nhóm màu phù hợp và tô có đậm nhạt sẽ giúp bức tranh kể được câu chuyện ấm áp của gia đình.\n- GV dặn dò: giữ tranh phẳng trong cặp, chuẩn bị cho tiết trưng bày và giới thiệu sản phẩm cuối chủ đề.","hs":"- HS dán tranh lên bảng nhóm đúng chủ đề, ghi tên và tên tranh vào góc bài.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì màu vàng cam làm bữa cơm trông rất ấm.\n- HS trả lời câu hỏi chốt và tự nhận xét về màu sắc trong bài của mình.\n- HS cất tranh phẳng phiu và ghi nhớ chuẩn bị cho tiết sau."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":29,"tiet":29,"bai":"Chủ đề 9: SINH HOẠT TRONG GIA ĐÌNH (Tiết 4)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được vẻ đẹp của các hoạt động sinh hoạt thường ngày trong gia đình.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, sản phẩm 3D) thể hiện hoạt động sinh hoạt gia đình.\n- Biết thể hiện dáng người, hình ảnh chính – phụ và không khí ấm cúng của gia đình.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 2.2 CB1a: Nhận biết được các công nghệ số đơn giản, phù hợp để chia sẻ dữ liệu, thông tin và nội dung số: HS xem trang trưng bày và tìm được tranh cùng nhóm hoạt động.","dodung":"- Giáo viên: hình ảnh, clip về hoạt động sinh hoạt gia đình; tranh sinh hoạt của hoạ sĩ và của HS; hình minh hoạ các bước vẽ dáng người; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm của HS ở Tiết 3.\n- GV khen ngợi và giới thiệu nội dung tiết học.","hs":"- HS trưng bày sản phẩm Tiết 3.\n- HS mở bài học."},{"ten":"2. Khám phá","gv":"- GV hướng dẫn HS hoàn thiện, chỉnh sửa và trang trí thêm cho tranh.\n- GV gợi ý cách đặt tên cho tranh.","hs":"- HS hoàn thiện, chỉnh sửa tranh.\n- HS đặt tên cho tranh."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS hoàn thành sản phẩm và chuẩn bị giới thiệu.\n- GV quan sát, hỗ trợ HS.","hs":"- HS hoàn thành sản phẩm.\n- HS chuẩn bị giới thiệu."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trưng bày, nhận xét cuối chủ đề: tranh thể hiện hoạt động gì, cảm xúc về gia đình.\n- GV dặn dò chuẩn bị chủ đề An toàn giao thông.","hs":"- HS trưng bày, giới thiệu tranh và cảm xúc về gia đình.\n- HS cùng nhận xét, đánh giá."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp tranh sinh hoạt gia đình của HS, ghép thành một trang trưng bày và xếp nhóm theo hoạt động: bữa cơm, dọn nhà, chăm em, cùng xem ti vi.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS tìm tranh của bạn cùng nhóm hoạt động với mình và nói hai bức giống nhau, khác nhau ở chỗ nào.\n⚠ (Miền 4: An toàn) Tranh vẽ chuyện trong nhà nên khi giới thiệu HS chỉ kể việc chung, không kể chuyện riêng của gia đình mình hay của gia đình bạn trước lớp.","hs":"- HS xem trang trưng bày và tìm được tranh cùng nhóm hoạt động.\n- HS so sánh được cách thể hiện của mình với của bạn."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":30,"tiet":30,"bai":"Chủ đề 10: AN TOÀN GIAO THÔNG (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được một số phương tiện, biển báo, tín hiệu và hành vi an toàn khi tham gia giao thông.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, mô hình, biển báo) về chủ đề an toàn giao thông.\n- Biết sử dụng hình, màu để truyền thông điệp về an toàn giao thông.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS gọi tên và nêu được ý nghĩa của một số biển báo, tín hiệu qua mô phỏng.","dodung":"- Giáo viên: hình ảnh, clip về giao thông, biển báo, tín hiệu đèn; tranh cổ động và sản phẩm mĩ thuật về an toàn giao thông để làm mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem hình ảnh/clip về giao thông và hỏi: Em thấy phương tiện, biển báo, tín hiệu nào?\n- GV khen ngợi và giới thiệu chủ đề.","hs":"- HS xem, kể tên phương tiện, biển báo, tín hiệu giao thông.\n- HS mở bài học, ghi tên bài."},{"ten":"2. Khám phá","gv":"- GV cho HS quan sát tranh cổ động, biển báo giao thông trong SGK; phân tích hình, màu, thông điệp.\n- GV gợi ý HS chọn một nội dung an toàn giao thông để thể hiện.","hs":"- HS quan sát, nhận ra hình, màu và ý nghĩa của biển báo, tranh cổ động.\n- HS chọn nội dung để thể hiện."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV hướng dẫn HS phác ý tưởng và bố cục cho sản phẩm về an toàn giao thông.\n- GV cho HS vẽ phác bố cục.","hs":"- HS phác ý tưởng và bố cục.\n- HS chia sẻ ý tưởng."},{"ten":"4. Vận dụng","gv":"- GV yêu cầu HS nêu ý tưởng và liên hệ việc chấp hành an toàn giao thông.\n- GV dặn dò chuẩn bị đồ dùng.","hs":"- HS nêu ý tưởng, liên hệ thực tế.\n- HS chuẩn bị đồ dùng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu mô phỏng một ngã tư có đèn tín hiệu và các biển báo, bấm cho đèn đổi màu, cho xe và người đi bộ di chuyển để HS thấy mỗi tín hiệu, mỗi biển báo điều khiển việc gì; mô phỏng cho phép dừng lại và làm lại, điều mà quan sát ngoài đường thật không làm được và cũng không an toàn.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS gọi tên biển báo và nói màu, hình dạng của biển ấy có ý nghĩa gì.\n⚠ (Miền 4: An toàn) HS quan sát ngã tư qua mô phỏng, tuyệt đối không tự ra đường đứng xem xe cộ để lấy tư liệu vẽ; ra đường phải có người lớn đi cùng.","hs":"- HS gọi tên và nêu được ý nghĩa của một số biển báo, tín hiệu qua mô phỏng.\n- HS nêu được vì sao biển báo dùng màu và hình dạng riêng."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":31,"tiet":31,"bai":"Chủ đề 10: AN TOÀN GIAO THÔNG (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được một số phương tiện, biển báo, tín hiệu và hành vi an toàn khi tham gia giao thông.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, mô hình, biển báo) về chủ đề an toàn giao thông.\n- Biết sử dụng hình, màu để truyền thông điệp về an toàn giao thông.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: hình ảnh, clip về giao thông, biển báo, tín hiệu đèn; tranh cổ động và sản phẩm mĩ thuật về an toàn giao thông để làm mẫu; bộ thẻ biển báo cấm, biển báo nguy hiểm, biển chỉ dẫn để HS nhận diện; hình minh hoạ các bước vẽ ô tô, xe máy, xe đạp đơn giản; thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính là giấy vẽ và bút chì; vật liệu thay thế dễ kiếm: mặt sau tờ lịch cũ, bìa carton làm mô hình biển báo, vỏ hộp sữa làm ô tô, giấy báo cũ, nắp chai làm bánh xe và đèn tín hiệu.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS đặt bản phác của Tiết 1 và đồ dùng lên bàn, kiểm tra nhanh và khen HS đã chọn được nội dung thông điệp.\n- GV tổ chức trò chơi Đèn tín hiệu: GV giơ thẻ màu đỏ, vàng, xanh, HS làm động tác dừng lại, chuẩn bị, đi; sau đó GV giơ hai thẻ biển báo và hỏi: Biển này nói điều gì?\n- GV hỏi thêm: Thông điệp em muốn gửi qua sản phẩm của mình là gì?\n- GV khen ngợi và giới thiệu nhiệm vụ tiết học: vẽ chi tiết hình ảnh cho sản phẩm về an toàn giao thông.","hs":"- HS đặt bản phác Tiết 1 và đồ dùng lên bàn, tự kiểm tra bút chì, tẩy, màu.\n- HS chơi trò Đèn tín hiệu, làm đúng động tác theo màu và trả lời nghĩa của biển báo.\n- HS nêu thông điệp của mình: đội mũ bảo hiểm khi ngồi sau xe máy, đi bộ trên vỉa hè, qua đường ở vạch kẻ.\n- HS mở SGK, ghi tên bài và chuẩn bị bản phác để vẽ tiếp."},{"ten":"2. Khám phá","gv":"- (8 phút) GV hướng dẫn HS vẽ chi tiết hình ảnh theo 4 bước: Bước 1 xác định hình chính chở thông điệp (người đội mũ bảo hiểm, bạn nhỏ qua đường trên vạch kẻ) và vẽ to gần giữa tranh; Bước 2 vẽ phương tiện bằng hình khối đơn giản; Bước 3 vẽ biển báo, đèn tín hiệu, vạch kẻ đường, vỉa hè; Bước 4 thêm chữ ngắn gọn cho thông điệp nếu làm tranh cổ động.\n- GV thị phạm chậm bước 2: ô tô là một hình chữ nhật nằm ghép với một hình thang ở trên và hai hình tròn làm bánh; xe đạp là hai hình tròn nối bằng các nét thẳng.\n- GV lưu ý kĩ thuật vẽ rõ thông điệp: hình chính vẽ to, đặt ở chỗ dễ thấy; biển báo vẽ đúng hình dạng và màu quy ước (biển cấm hình tròn viền đỏ, biển nguy hiểm hình tam giác viền đỏ, biển chỉ dẫn hình vuông màu xanh); chữ ít, to, dễ đọc.\n- GV hỏi: Vì sao biển báo phải dùng màu đỏ và màu vàng? GV chốt và nhắc HS vẽ nhẹ tay để dễ sửa, cắt bìa làm mô hình thì dùng kéo cẩn thận.","hs":"- HS quan sát và nhắc lại 4 bước vẽ chi tiết cho sản phẩm về an toàn giao thông.\n- HS theo dõi GV thị phạm, vẽ thử một ô tô và một xe đạp bằng hình khối đơn giản ra giấy nháp.\n- HS nhắc lại quy ước hình dạng và màu của ba loại biển báo đã học.\n- HS trả lời: màu đỏ và vàng nổi bật, nhìn từ xa cũng thấy rõ nên giúp người đi đường chú ý."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (15 phút) GV cho HS thực hành hoàn thiện phần hình cho sản phẩm về an toàn giao thông theo đúng 4 bước; HS có thể chọn làm tranh cổ động, mô hình biển báo hoặc mô hình ngã tư đường phố theo nhóm 4.\n- GV nêu yêu cầu cụ thể: sản phẩm có hình chính rõ thông điệp, ít nhất một biển báo hoặc đèn tín hiệu vẽ đúng quy ước, hình không dính sát mép giấy.\n- GV đi từng bàn hỗ trợ: vẽ mẫu lại hình phương tiện cho HS còn lúng túng, gợi ý nhóm làm mô hình dùng vỏ hộp sữa làm ô tô, nắp chai làm bánh xe, ống hút cắm bìa làm cột biển báo.\n- GV nhắc an toàn khi dùng kéo và keo, nhắc HS tẩy nhẹ tay; báo trước còn 3 phút để hoàn thiện, gom giấy vụn và cất đồ dùng.","hs":"- HS thực hành vẽ chi tiết theo 4 bước, vẽ hình chính chở thông điệp trước.\n- HS vẽ hoặc làm biển báo, đèn tín hiệu đúng hình dạng và màu quy ước.\n- HS trong nhóm phân công nhau làm mô hình, trao đổi cách sắp xếp cho rõ thông điệp.\n- HS hoàn thiện bài, gom giấy vụn, cất kéo và keo đúng chỗ, lau sạch bàn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày bản vẽ hình và mô hình trên bảng nhóm theo chủ đề: bảng Đi bộ an toàn, bảng Đội mũ bảo hiểm, bảng Ngã tư đường phố.\n- GV nêu tiêu chí nhận xét: (1) có hình chính rõ, người xem hiểu ngay thông điệp; (2) bố cục cân đối, hình chính nổi bật; (3) biển báo, tín hiệu vẽ đúng quy ước; (4) sản phẩm sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem, dán sao vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV hỏi chốt: Sản phẩm của bạn nhắc chúng ta điều gì khi tham gia giao thông? GV chốt: hình ảnh và màu sắc rõ ràng sẽ giúp thông điệp an toàn giao thông đến với người xem nhanh nhất.\n- GV dặn dò chuẩn bị màu vẽ, khăn lau, hộp nước cho tiết sau để tô màu hoàn thiện sản phẩm.","hs":"- HS đặt sản phẩm lên bảng nhóm đúng chủ đề, ghi tên vào góc bài.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì nhìn là hiểu ngay phải đội mũ bảo hiểm.\n- HS trả lời câu hỏi chốt và nêu một việc mình sẽ làm để tham gia giao thông an toàn.\n- HS tự đánh giá bài mình theo tiêu chí và ghi nhớ chuẩn bị màu cho tiết sau."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":32,"tiet":32,"bai":"Chủ đề 10: AN TOÀN GIAO THÔNG (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được một số phương tiện, biển báo, tín hiệu và hành vi an toàn khi tham gia giao thông.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, mô hình, biển báo) về chủ đề an toàn giao thông.\n- Biết sử dụng hình, màu để truyền thông điệp về an toàn giao thông.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS giải thích được vì sao biển báo và tranh cổ động cần màu tương phản mạnh.","dodung":"- Giáo viên: hình ảnh, clip về giao thông, biển báo, tín hiệu đèn; tranh cổ động và sản phẩm mĩ thuật về an toàn giao thông để làm mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra bản vẽ hình và đồ dùng của HS ở Tiết 2.\n- GV khen ngợi và giới thiệu nội dung tiết học.","hs":"- HS trình bày bản vẽ hình và đồ dùng.\n- HS mở bài học."},{"ten":"2. Khám phá","gv":"- GV hướng dẫn HS chọn và phối màu cho sản phẩm; gợi ý dùng màu nổi bật (đỏ, vàng, xanh) đúng với tín hiệu, biển báo.\n- GV thị phạm cách tô màu gọn, rõ.","hs":"- HS quan sát cách phối màu.\n- HS chọn màu cho sản phẩm."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS thực hành tô màu, hoàn thiện sản phẩm.\n- GV quan sát, hỗ trợ HS hoàn thành.","hs":"- HS thực hành tô màu, hoàn thiện sản phẩm.\n- HS chia sẻ tiến độ."},{"ten":"4. Vận dụng","gv":"- GV cho HS trưng bày sản phẩm đã tô màu, cùng nhận xét về màu sắc, thông điệp.\n- GV dặn dò chuẩn bị cho tiết trưng bày.","hs":"- HS trưng bày, nhận xét về màu sắc.\n- HS chuẩn bị cho tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu cùng một biển báo với hai cách phối màu: một bản đúng chuẩn màu tương phản mạnh và một bản màu nhạt nhoà, rồi thu nhỏ cả hai trên màn hình để HS thấy bản tương phản mạnh vẫn đọc được còn bản kia thì không.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS rút ra vì sao tranh cổ động và biển báo phải dùng màu tương phản mạnh, chữ to và ít chi tiết.\n⚠ (Miền 4: An toàn) Màu và hình của biển báo giao thông do nhà nước quy định, HS không tự đổi màu biển báo thật khi vẽ để tránh gây hiểu nhầm cho người xem.","hs":"- HS giải thích được vì sao biển báo và tranh cổ động cần màu tương phản mạnh.\n- HS chọn được cặp màu đủ rõ cho sản phẩm cổ động của mình."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":33,"tiet":33,"bai":"Chủ đề 10: AN TOÀN GIAO THÔNG (Tiết 4)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được một số phương tiện, biển báo, tín hiệu và hành vi an toàn khi tham gia giao thông.\n- Vẽ/tạo được sản phẩm mĩ thuật (tranh, mô hình, biển báo) về chủ đề an toàn giao thông.\n- Biết sử dụng hình, màu để truyền thông điệp về an toàn giao thông.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 2.3 CB1a: Xác định được các dịch vụ số đơn giản để có thể tham gia vào xã hội: HS đóng góp tranh và lời tuyên truyền cho trang cổ động của lớp.","dodung":"- Giáo viên: hình ảnh, clip về giao thông, biển báo, tín hiệu đèn; tranh cổ động và sản phẩm mĩ thuật về an toàn giao thông để làm mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm của HS ở Tiết 3.\n- GV khen ngợi và giới thiệu nội dung tiết học.","hs":"- HS trưng bày sản phẩm Tiết 3.\n- HS mở bài học."},{"ten":"2. Khám phá","gv":"- GV hướng dẫn HS hoàn thiện, thêm khẩu hiệu/thông điệp cho sản phẩm về an toàn giao thông.\n- GV gợi ý cách viết khẩu hiệu ngắn gọn.","hs":"- HS hoàn thiện và thêm thông điệp cho sản phẩm.\n- HS viết khẩu hiệu an toàn giao thông."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV cho HS hoàn thành sản phẩm và chuẩn bị giới thiệu.\n- GV quan sát, hỗ trợ HS.","hs":"- HS hoàn thành sản phẩm.\n- HS chuẩn bị giới thiệu."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trưng bày, nhận xét cuối chủ đề: sản phẩm truyền thông điệp gì về an toàn giao thông.\n- GV dặn dò ôn tập, chuẩn bị kiểm tra, đánh giá cuối năm.","hs":"- HS trưng bày, giới thiệu sản phẩm và thông điệp.\n- HS cùng nhận xét, đánh giá."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp tranh cổ động an toàn giao thông của HS và ghép thành một trang tuyên truyền của lớp có khẩu hiệu và ảnh tranh, gửi cho các lớp khác cùng xem trong buổi sinh hoạt dưới cờ.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS tập nói lời tuyên truyền ngắn đi kèm tranh của mình sao cho bạn lớp khác nghe là hiểu ngay.\n⚠ (Miền 4: An toàn) Trang tuyên truyền ghi tên lớp và tên tác giả từng bức; chỉ chia sẻ trong phạm vi nhà trường; thông điệp phải đúng luật giao thông, chưa chắc thì hỏi lại GV.","hs":"- HS đóng góp tranh và lời tuyên truyền cho trang cổ động của lớp.\n- HS nói được thông điệp an toàn giao thông ngắn gọn, dễ hiểu."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":34,"tiet":34,"bai":"Ôn tập, đánh giá cuối năm học","yccd":"1. Năng lực mĩ thuật\n- Củng cố, hệ thống kiến thức, kĩ năng mĩ thuật đã học trong cả năm học.\n- Vận dụng kiến thức đã học để thực hiện một sản phẩm mĩ thuật theo ý thích.\n- Tự đánh giá được sản phẩm của mình và của bạn, nêu được sự tiến bộ của bản thân.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.","dodung":"- GV: bảng hệ thống các chủ đề cả năm; một số sản phẩm mĩ thuật tiêu biểu của HS trong năm; bảng tiêu chí đánh giá đơn giản viết to treo trước lớp; phiếu tự đánh giá có ba mức đạt, tốt, cần cố gắng; sao giấy để HS bình chọn; thiết bị trình chiếu học liệu số.\n- HS: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn. Vật liệu chính do HS tự chọn theo nội dung mình thể hiện; vật liệu thay thế dễ kiếm: giấy báo cũ, bìa carton, vỏ hộp, lá cây khô, hột hạt, dây len, vải vụn, nắp chai.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV cùng HS hệ thống lại các chủ đề đã học trong năm bằng sơ đồ nhánh trên bảng: từ giữa là Mĩ thuật 3, các nhánh là Hoa văn trang phục, Màu sắc, Khối, Vật liệu, Thầy cô, Cảnh vật, Chân dung, Sinh hoạt gia đình, An toàn giao thông.\n- GV tổ chức trò chơi Tiếp sức: mỗi tổ cử 3 HS lên gắn thẻ tên chủ đề vào đúng nhánh trong 1 phút.\n- GV hỏi: Chủ đề nào em thích nhất và em đã học được kĩ năng gì từ chủ đề đó?\n- GV giới thiệu nội dung tiết kiểm tra, đánh giá cuối năm và treo bảng tiêu chí đánh giá cho HS đọc trước.","hs":"- HS nhắc lại tên các chủ đề đã học và những kiến thức chính của từng chủ đề.\n- HS các tổ chơi tiếp sức, gắn thẻ tên chủ đề vào đúng nhánh của sơ đồ.\n- HS trả lời: em thích chủ đề Vẻ đẹp của khối vì em học được cách nặn và tạo dáng chuyển động.\n- HS lắng nghe yêu cầu, đọc bảng tiêu chí đánh giá và hỏi lại chỗ chưa rõ."},{"ten":"2. Khám phá","gv":"- (6 phút) GV nêu yêu cầu bài kiểm tra: mỗi HS chọn một nội dung yêu thích đã học trong năm để thể hiện thành một sản phẩm mĩ thuật hoàn chỉnh.\n- GV gợi ý các hướng lựa chọn: vẽ tranh (phong cảnh, chân dung, sinh hoạt), trang trí đồ vật bằng hoa văn, nặn hoặc ghép vật liệu tạo sản phẩm 3D, làm tranh cổ động.\n- GV hỏi để HS xác định rõ dự định: Em chọn nội dung gì? Em dùng chất liệu nào? Sản phẩm của em sẽ có hình ảnh chính là gì?\n- GV nhắc lại tiêu chí đánh giá để HS bám vào khi làm bài và lưu ý an toàn khi dùng kéo, keo, màu; chọn việc vừa sức để làm kịp trong tiết học.","hs":"- HS chọn nội dung và hình thức thể hiện phù hợp với khả năng của mình.\n- HS nêu dự định: em vẽ tranh phong cảnh quê em bằng màu sáp, hình chính là cây đa và con đường.\n- HS chuẩn bị đồ dùng, vật liệu cần dùng và bày gọn trên bàn.\n- HS đọc lại tiêu chí đánh giá và nhắc lại quy định an toàn, vệ sinh khi thực hành."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- (16 phút) GV cho HS thực hành hoàn thiện sản phẩm theo trình tự: Bước 1 phác bố cục và xác định hình chính; Bước 2 vẽ hoặc tạo hình chi tiết; Bước 3 thể hiện màu, chú ý đậm nhạt; Bước 4 hoàn thiện, đặt tên sản phẩm và ghi tên mình.\n- GV quan sát, hỗ trợ HS gặp khó khăn nhưng không làm thay, ghi nhận sự tiến bộ của từng HS so với đầu năm vào sổ theo dõi.\n- GV nhắc HS bám tiêu chí: hình ảnh chính rõ, bố cục cân đối, màu sắc có đậm nhạt, bài sạch sẽ và có ý tưởng riêng.\n- GV báo trước còn 3 phút để hoàn thiện, thu dọn vật liệu thừa, rửa tay, lau bàn và chuẩn bị trưng bày.","hs":"- HS thực hành theo 4 bước, vận dụng các kiến thức và kĩ năng đã học trong cả năm.\n- HS chủ động chọn cách làm phù hợp, tự giải quyết khó khăn trước khi nhờ GV giúp.\n- HS đối chiếu bài của mình với tiêu chí và chỉnh sửa chỗ chưa đạt.\n- HS hoàn thiện, đặt tên sản phẩm, ghi tên mình, thu dọn vật liệu thừa và lau sạch bàn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV tổ chức trưng bày thành phòng tranh mini cuối năm ở góc lớp, chia theo bảng nhóm: bảng Tranh vẽ, bảng Sản phẩm 3D, bảng Đồ vật trang trí.\n- GV nêu tiêu chí đánh giá sản phẩm: (1) có hình ảnh chính rõ ràng, đúng nội dung đã chọn; (2) bố cục cân đối, hài hoà; (3) màu sắc có đậm nhạt, phù hợp nội dung; (4) sản phẩm sạch sẽ, hoàn chỉnh, có ý tưởng riêng.\n- GV phát phiếu tự đánh giá, hướng dẫn HS đánh dấu mức đạt được cho từng tiêu chí; sau đó cho HS đi xem, dán sao và nhận xét bạn theo mẫu: Mình thích bài này vì...\n- GV nhận xét, đánh giá kết quả học tập cả năm, nêu tên những HS có tiến bộ rõ rệt và động viên cả lớp.\n- GV giới thiệu tiết Trưng bày sản phẩm cuối năm và dặn HS chọn sẵn hai sản phẩm tâm đắc nhất, giữ phẳng để mang tới trưng bày.","hs":"- HS đặt sản phẩm lên đúng bảng nhóm, ghi tên và tên sản phẩm vào mẩu giấy bên cạnh.\n- HS trưng bày, giới thiệu ngắn về sản phẩm: tên sản phẩm, nội dung, chất liệu đã dùng.\n- HS tự đánh giá vào phiếu theo bốn tiêu chí, sau đó đi xem và dán sao cho bài mình thích.\n- HS nhận xét sản phẩm của bạn theo mẫu và nêu được điều mình học thêm được từ bài của bạn.\n- HS lắng nghe nhận xét cuối năm và chọn hai sản phẩm tâm đắc để chuẩn bị cho tiết trưng bày."}]},
{"lop":3,"mon":"Mĩ thuật","tuan":35,"tiet":35,"bai":"TRƯNG BÀY SẢN PHẨM CUỐI NĂM","yccd":"1. Năng lực mĩ thuật\n- Biết lựa chọn, sắp xếp và trưng bày sản phẩm mĩ thuật đã thực hiện trong năm học.\n- Giới thiệu, chia sẻ được cảm nhận về sản phẩm của mình và của bạn.\n- Cảm nhận được sự trưởng thành, tiến bộ của bản thân qua các sản phẩm mĩ thuật.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ ý tưởng và hợp tác nhóm khi thực hành.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện và vật liệu phù hợp để tạo sản phẩm mĩ thuật.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm mĩ thuật; giữ gìn vệ sinh, sắp xếp đồ dùng gọn gàng.\n- Yêu thích cái đẹp, trân trọng sản phẩm của mình và của bạn; có ý thức vận dụng mĩ thuật vào cuộc sống.\n4. Tích hợp\n- Năng lực số 2.2 CB1a: Nhận biết được các công nghệ số đơn giản, phù hợp để chia sẻ dữ liệu, thông tin và nội dung số: HS sắp xếp được góc trưng bày và nhận ra cách bày làm sản phẩm nổi bật.","dodung":"- Giáo viên: không gian trưng bày (bảng, tường, bàn); các sản phẩm mĩ thuật của HS trong năm; giấy, bìa, băng dính để trưng bày; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 3, Vở bài tập Mĩ thuật 3, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tạo không khí ngày hội, giới thiệu buổi trưng bày sản phẩm mĩ thuật cuối năm.\n- GV nêu ý nghĩa của việc trưng bày, giới thiệu sản phẩm.","hs":"- HS chuẩn bị tâm thế, mang các sản phẩm đã làm.\n- HS lắng nghe."},{"ten":"2. Khám phá","gv":"- GV hướng dẫn HS lựa chọn, phân loại và sắp xếp sản phẩm theo chủ đề/nhóm.\n- GV gợi ý cách trưng bày đẹp, khoa học.","hs":"- HS lựa chọn, sắp xếp sản phẩm theo nhóm/chủ đề.\n- HS trang trí khu trưng bày."},{"ten":"3. Luyện tập – Sáng tạo","gv":"- GV tổ chức cho các nhóm hoàn thiện khu trưng bày và tập giới thiệu sản phẩm.\n- GV quan sát, hỗ trợ HS.","hs":"- HS hoàn thiện khu trưng bày của nhóm.\n- HS tập giới thiệu sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV tổ chức cho HS tham quan, giới thiệu và chia sẻ cảm nhận về sản phẩm; bình chọn sản phẩm ấn tượng.\n- GV nhận xét, tổng kết, động viên và khích lệ tinh thần yêu mĩ thuật của HS.","hs":"- HS tham quan, giới thiệu sản phẩm và chia sẻ cảm nhận.\n- HS bình chọn, nêu sự tiến bộ của bản thân."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV hướng dẫn HS sắp xếp góc trưng bày rồi chụp lại thành bộ ảnh triển lãm cuối năm; HS so sánh ảnh chụp trước và sau khi sắp xếp để thấy cách bày cân đối, có khoảng trống hợp lí thì sản phẩm nổi bật hơn.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS đóng vai người hướng dẫn tham quan, giới thiệu góc trưng bày của tổ mình cho tổ bạn.\n⚠ (Miền 4: An toàn) Bộ ảnh triển lãm ghi tên tác giả từng sản phẩm; chỉ chiếu trong buổi tổng kết của lớp và của trường, muốn đưa ra ngoài phải hỏi ý kiến các bạn và cha mẹ.","hs":"- HS sắp xếp được góc trưng bày và nhận ra cách bày làm sản phẩm nổi bật.\n- HS giới thiệu được góc trưng bày của tổ mình cho bạn nghe."}]}
];
